{"command":"cat > /workspace/uctags.py <<'PYEOF'
#!/usr/bin/env python3
import os, sys, re, json, fnmatch, time

PROG = os.path.basename(sys.argv[0]) or "ctags"
START_TIME = time.time()
DATA = None
def load_data():
    global DATA
    if DATA is not None:
        return DATA
    # data file is embedded alongside: try exe dir / src_data
    candidates=[]
    try:
        exe=os.path.realpath(sys.argv[0])
        d=os.path.dirname(exe)
        candidates += [os.path.join(d,"data.json"), os.path.join(d,"src_data","data.json")]
    except Exception:
        pass
    candidates += ["src_data/data.json","./src_data/data.json", os.path.join(os.path.dirname(os.path.abspath(__file__)),"src_data","data.json"), os.path.join(os.path.dirname(os.path.abspath(__file__)),"data.json")]
    # embedded fallback: if __EMBEDDED__ placeholder replaced?
    for c in candidates:
        if os.path.exists(c):
            DATA=json.load(open(c))
            return DATA
    DATA={"caps":{},"per":{},"versions":""}
    return DATA

def eprint(msg):
    sys.stderr.write(msg)
    if not msg.endswith("\n"):
        sys.stderr.write("\n")

def out_write(s):
    # write preserving surrogateescape bytes
    try:
        sys.stdout.buffer.write(s.encode('utf-8','surrogateescape'))
    except Exception:
        sys.stdout.write(s)

def errline(msg):
    sys.stderr.write(f"{PROG}: {msg}\n")

# ---- parsed metadata ----
class Meta:
    def __init__(self):
        d=load_data()
        self.caps=d.get("caps",{})
        self.per=d.get("per",{})
        self.versions_raw=d.get("versions","")
        self.languages=[]  # canonical names without disabled
        self.disabled_default=set()
        for line in self.caps.get("languages","").splitlines():
            if line.endswith(" [disabled]"):
                name=line[:-len(" [disabled]")]
                self.disabled_default.add(name)
                self.languages.append(name)
            elif line.strip():
                self.languages.append(line.strip())
        self.lang_lower={l.lower():l for l in self.languages}
        self.versions={}
        for line in self.versions_raw.splitlines():
            m=re.match(r'^(.*?) => parser/(.*?): (\S+)',line)
            if m:
                self.versions[m.group(1)]=m.group(3)
        # kinds per lang from kinds-full
        self.kinds={}  # lang -> list dict letter,name,enabled,refonly,nroles,master,ver,desc
        self.kind_by_letter={}
        self.kind_by_name={}
        fnmap={self.filename_for(l):l for l in self.languages}
        for fn,txt in self.per.get("list-kinds-full",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            lst=[]
            for line in txt.splitlines():
                if line.startswith("#") or not line.strip(): continue
                # format with fixed-ish columns but split max
                parts=line.split()
                if len(parts)<7: continue
                letter=parts[0]; name=parts[1]; enabled=parts[2]; refonly=parts[3]; nroles=parts[4]; master=parts[5]; ver=parts[6]
                # description is rest after ver: find
                # locate ver token index
                idx=line.find(ver, line.find(master)+len(master))
                desc=line[idx+len(ver):].strip() if idx>=0 else ""
                ent=dict(letter=letter,name=name,enabled=(enabled=="yes"),refonly=(refonly=="yes"),nroles=nroles,master=master,ver=ver,desc=desc,raw=line)
                lst.append(ent)
            self.kinds[lang]=lst
            self.kind_by_letter[lang]={e['letter']:e for e in lst}
            self.kind_by_name[lang]={e['name']:e for e in lst}
        # fields
        self.fields_all=[]  # list dict
        self.fields_by_letter={}
        for line in self.caps.get("fields","").splitlines():
            if line.startswith("#") or not line.strip(): continue
            # letter, name, enabled, language, jstype, fixed, op, ver, desc
            m=re.match(r'^(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(\S+)\s+(.*)$',line)
            if not m: continue
            ent=dict(letter=m.group(1),name=m.group(2),enabled=(m.group(3)=="yes"),language=m.group(4),jstype=m.group(5),fixed=m.group(6),op=m.group(7),ver=m.group(8),desc=m.group(9),raw=line)
            self.fields_all.append(ent)
            if ent['letter']!='-':
                self.fields_by_letter[ent['letter']]=ent
        # per-lang fields (name based)
        self.lang_fields={}
        for fn,txt in self.per.get("list-fields",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            lst=[]
            for line in txt.splitlines():
                if line.startswith("#") or not line.strip(): continue
                m=re.match(r'^(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(\S+)\s+(.*)$',line)
                if m:
                    lst.append(dict(letter=m.group(1),name=m.group(2),enabled=(m.group(3)=="yes"),language=m.group(4),desc=m.group(9),raw=line))
            if lst:
                self.lang_fields[lang]=lst
        # extras
        self.extras_all=[]
        self.extras_by_letter={}
        for line in self.caps.get("extras","").splitlines():
            if line.startswith("#") or not line.strip(): continue
            m=re.match(r'^(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(.*)$',line)
            if not m: continue
            ent=dict(letter=m.group(1),name=m.group(2),enabled=(m.group(3)=="yes"),language=m.group(4),fixed=m.group(5),ver=m.group(6),desc=m.group(7),raw=line)
            self.extras_all.append(ent)
            if ent['letter']!='-':
                self.extras_by_letter[ent['letter']]=ent
        self.lang_extras={}
        for fn,txt in self.per.get("list-extras",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            lst=[]
            for line in txt.splitlines():
                if line.startswith("#") or not line.strip(): continue
                m=re.match(r'^(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(.*)$',line)
                if m:
                    lst.append(dict(letter=m.group(1),name=m.group(2),enabled=(m.group(3)=="yes"),language=m.group(4),desc=m.group(7),raw=line))
            if lst:
                self.lang_extras[lang]=lst
        # pseudo
        self.pseudo=[]
        for line in self.caps.get("pseudo","").splitlines():
            if line.startswith("#") or not line.strip(): continue
            m=re.match(r'^(\S+)\s+(on|off)\s+(\S+)\s+(.*)$',line)
            if m:
                self.pseudo.append(dict(name=m.group(1),enabled=(m.group(2)=="on"),ver=m.group(3),desc=m.group(4),raw=line))
        # maps
        self.map_ext={}  # lang -> [ext]
        for fn,txt in self.per.get("list-map-extensions",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            exts=[l.strip() for l in txt.splitlines() if l.strip() and not l.startswith("#")]
            if exts:
                self.map_ext[lang]=exts
        self.map_pat={}
        for fn,txt in self.per.get("list-map-patterns",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            pats=[l.strip() for l in txt.splitlines() if l.strip() and not l.startswith("#")]
            if pats:
                self.map_pat[lang]=pats
        self.map_rex={}
        for fn,txt in self.per.get("list-map-rexprs",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            vals=[l for l in txt.splitlines() if l.strip() and not l.startswith("#")]
            if vals:
                self.map_rex[lang]=vals
        # Build ext->lang and pat list preserving language order (?) Maps all order is alphabetical? Languages list order is alphabetical-ish
        # roles per lang
        self.roles={}
        for fn,txt in self.per.get("list-roles",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            lst=[]
            for line in txt.splitlines():
                if line.startswith("#") or not line.strip(): continue
                # KIND(L/N) NAME ENABLED VER DESC
                m=re.match(r'^(\S+)/(\S+)\s+(\S+)\s+(on|off)\s+(\S+)\s+(.*)$',line.strip())
                if m:
                    lst.append(dict(letter=m.group(1),kind=m.group(2),name=m.group(3),enabled=(m.group(4)=="on"),ver=m.group(5),desc=m.group(6),raw=line))
            if lst:
                self.roles[lang]=lst
        # aliases per lang: from caps aliases (LANGUAGE ALIAS)
        self.aliases={}
        for line in self.caps.get("aliases","").splitlines():
            if line.startswith("#") or not line.strip(): continue
            parts=line.split()
            if len(parts)>=2:
                self.aliases.setdefault(parts[0],[]).append(parts[1])
        # Also aliases from describe includes shebang patterns: parse describe Aliases section
        self.shebang_aliases={}  # lang -> patterns
        for fn,txt in self.per.get("describe",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            sec=None
            for line in txt.splitlines():
                if line.strip()=="Aliases":
                    sec="alias"; continue
                if sec=="alias":
                    if line.startswith("----"): continue
                    if line.startswith("#ALIAS"): continue
                    if line.strip()=="" : continue
                    if line.strip()=="Kinds" or line.startswith("Kinds"):
                        break
                    # alias lines until blank blank?
                    if line.strip():
                        self.shebang_aliases.setdefault(lang,[]).append(line.strip())
                    else:
                        # continue maybe
                        pass
                    # End when next section header detected via later check
                    if line.strip()=="Kinds":
                        break
            # clean: remove possible trailing section words
        # Fix shebang aliases: many are from describe; ensure not include 'Kinds'
        for k in list(self.shebang_aliases.keys()):
            self.shebang_aliases[k]=[a for a in self.shebang_aliases[k] if a not in ("Kinds",) and not a.startswith("----")]
    def filename_for(self,lang):
        return lang.replace("/","_").replace("#","Sharp").replace("+","P")+".txt"
    def canon(self,name):
        if name is None:
            return None
        if name in self.languages:
            return name
        l=name.lower()
        if l in self.lang_lower:
            return self.lang_lower[l]
        # special aliases? c++ etc lower works
        return None

META=None
def meta():
    global META
    if META is None:
        META=Meta()
    return META

# ---- Options state ----
class State:
    def __init__(self):
        m=meta()
        self.enabled_langs=set(m.languages)-set(m.disabled_default)
        # kinds enabled per lang: dict lang->set letters
        self.kinds_enabled={}
        for lang,lst in m.kinds.items():
            self.kinds_enabled[lang]={e['letter'] for e in lst if e['enabled']}
        self.fields_enabled=set()
        # default fields VALUE from help [fks] plus? Also t typeref? In list-fields, enabled = N,F,P,T,f,k,s,t
        for e in m.fields_all:
            if e['language']=="NONE" and e['letter']!='-' and e['enabled']:
                self.fields_enabled.add(e['letter'])
        # lang fields enabled names
        self.lang_fields_enabled={}
        for lang,lst in m.lang_fields.items():
            self.lang_fields_enabled[lang]={e['name'] for e in lst if e['enabled']}
        self.extras_enabled=set()
        for e in m.extras_all:
            if e['language']=="NONE" and e['letter']!='-' and e['enabled']:
                self.extras_enabled.add(e['letter'])
        # extra names enabled (for - and letter)
        self.extra_names_enabled={e['name'] for e in m.extras_all if e['enabled']}
        self.lang_extra_names_enabled={}
        for lang,lst in m.lang_extras.items():
            self.lang_extra_names_enabled[lang]={e['name'] for e in lst if e['enabled']}
        self.pseudo_enabled={e['name'] for e in m.pseudo if e['enabled']}
        self.sort="yes"  # yes/no/foldcase
        self.excmd="mix"
