def load_config_stage(state, verbose_log):
    # verbose_log is list of strings to emit if verbose later? But verbose may be enabled via config or cmdline initial scan.
    # We need determine verbose early: scan cmdline args for --verbose/-V before config. Original: "Reading initial options from command line" after config stages (?) verbose output includes config stages regardless because -V on cmdline triggers early.
    # Approach: caller determines initial_verbose from raw argv, passes via state.verbose_initial
    # Stages:
    stages=[]
    # stage1
    files1=[]
    xdg=os.environ.get("XDG_CONFIG_HOME")
    home=os.environ.get("HOME")
    dirs1=[]
    if xdg:
        dirs1.append(os.path.join(xdg,"ctags"))
    if home:
        dirs1.append(os.path.join(home,".config","ctags"))
    for d in dirs1:
