    stages.append((f"Entering configuration stage: loading file(s) under $XDG_CONFIG_HOME and $HOME/.config", files1))
    files2=[]
    if home:
        files2.extend(list_ctags_files_in_dir(os.path.join(home,".ctags.d")))
