# Long options that are parametric (may have optional value) vs boolean
PARAMETRIC=set("""describe-language etags-include exclude exclude-exception excmd extra extras fields filter-terminator format help help-full if0 input-encoding output-encoding lang language language-force languages langdef langmap license list-aliases list-excludes list-extras list-features list-fields list-kinds list-kinds-full list-languages list-maps list-map-extensions list-map-patterns list-map-rexprs list-mline-regex-flags list-output-formats list-params list-pseudo-tags list-regex-flags list-roles list-subparsers maxdepth optlib-dir options options-maybe output-format pattern-length-limit pseudo-tags sort tag-relative totals version _anonhash _dump-keywords _dump-options _dump-prelude _echo _force-initializing _force-quit _interactive _list-extradef-flags _list-fielddef-flags _list-kinddef-flags _list-langdef-flags _list-mtable-regex-flags _list-operators _list-roledef-flags _xformat""".split())
BOOLEAN=set("append file-scope file-tags filter guess-language-eagerly line-directives links machinable put-field-prefix print-language quiet recurse verbose with-list-header _fatal-warnings".split())

def is_known_long(state,name):
    m=meta()
    if name in PARAMETRIC or name in BOOLEAN:
        return True
    # prefixes
    prefixes=["kinds-","fields-","extras-","roles-","alias-","map-","param-","kinddef-","regex-","mline-regex-","input-encoding-","_extradef-","_fielddef-","_mtable-regex-","_mtable-extend-","_paramdef-","_prelude-","_pretend-","_roledef-","_scopesep-","_sequel-","_tabledef-"]
    for p in prefixes:
