def split_long(arg):
    # arg without --
    if "=" in arg:
        k,v=arg.split("=",1)
        return k,v,True
    else:
        return arg,None,False

def process_option_tokens(state, tokens, verbose_log, in_options_file=False):
    # tokens is list of argv strings (for cmdline stage, caller iterates; for option file single)
    # This function processes each token sequentially, handling short options consuming next token etc.
    # For cmdline, files are collected into state.files after options; but interleaving: original error "-f option may not follow a file name" when option file contained file then cmdline -f ... Complicated.
    # Simplification: caller for cmdline will handle iteration and call process_single for options, accumulating files.
    i=0
    while i<len(tokens):
        tok=tokens[i]
        consumed, nxt = process_single_token(state, tok, tokens, i, verbose_log, in_options_file)
        i=nxt

