def out_write(s):
    # write preserving surrogateescape bytes
    try:
        sys.stdout.buffer.write(s.encode('utf-8','surrogateescape'))
    except Exception:
        sys.stdout.write(s)

def errline(msg):
    sys.stderr.write(f"{PROG}: {msg}\n")

# ---- parsed metadata ----
class Meta:
    def __init__(self):
        d=load_data()
        self.caps=d.get("caps",{})
        self.per=d.get("per",{})
        self.versions_raw=d.get("versions","")
        self.languages=[]  # canonical names without disabled
        self.disabled_default=set()
        for line in self.caps.get("languages","").splitlines():
            if line.endswith(" [disabled]"):
                name=line[:-len(" [disabled]")]
                self.disabled_default.add(name)
                self.languages.append(name)
            elif line.strip():
                self.languages.append(line.strip())
        self.lang_lower={l.lower():l for l in self.languages}
        self.versions={}
        for line in self.versions_raw.splitlines():
            m=re.match(r'^(.*?) => parser/(.*?): (\S+)',line)
            if m:
                self.versions[m.group(1)]=m.group(3)
        # kinds per lang from kinds-full
        self.kinds={}  # lang -> list dict letter,name,enabled,refonly,nroles,master,ver,desc
        self.kind_by_letter={}
        self.kind_by_name={}
        fnmap={self.filename_for(l):l for l in self.languages}
        for fn,txt in self.per.get("list-kinds-full",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            lst=[]
            for line in txt.splitlines():
                if line.startswith("#") or not line.strip(): continue
                # format with fixed-ish columns but split max
                parts=line.split()
                if len(parts)<7: continue
                letter=parts[0]; name=parts[1]; enabled=parts[2]; refonly=parts[3]; nroles=parts[4]; master=parts[5]; ver=parts[6]
                # description is rest after ver: find
                # locate ver token index
                idx=line.find(ver, line.find(master)+len(master))
                desc=line[idx+len(ver):].strip() if idx>=0 else ""
                ent=dict(letter=letter,name=name,enabled=(enabled=="yes"),refonly=(refonly=="yes"),nroles=nroles,master=master,ver=ver,desc=desc,raw=line)
                lst.append(ent)
            self.kinds[lang]=lst
            self.kind_by_letter[lang]={e['letter']:e for e in lst}
            self.kind_by_name[lang]={e['name']:e for e in lst}
        # fields
        self.fields_all=[]  # list dict
        self.fields_by_letter={}
        for line in self.caps.get("fields","").splitlines():
            if line.startswith("#") or not line.strip(): continue
            # letter, name, enabled, language, jstype, fixed, op, ver, desc
            m=re.match(r'^(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(\S+)\s+(.*)$',line)
            if not m: continue
            ent=dict(letter=m.group(1),name=m.group(2),enabled=(m.group(3)=="yes"),language=m.group(4),jstype=m.group(5),fixed=m.group(6),op=m.group(7),ver=m.group(8),desc=m.group(9),raw=line)
            self.fields_all.append(ent)
            if ent['letter']!='-':
                self.fields_by_letter[ent['letter']]=ent
        # per-lang fields (name based)
        self.lang_fields={}
        for fn,txt in self.per.get("list-fields",{}).items():
