            m=re.match(r'^(\S+)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(yes|no)\s+(\S+)\s+(.*)$',line)
            if not m: continue
            ent=dict(letter=m.group(1),name=m.group(2),enabled=(m.group(3)=="yes"),language=m.group(4),fixed=m.group(5),ver=m.group(6),desc=m.group(7),raw=line)
            self.extras_all.append(ent)
            if ent['letter']!='-':
                self.extras_by_letter[ent['letter']]=ent
        self.lang_extras={}
        for fn,txt in self.per.get("list-extras",{}).items():
