            m=re.match(r'^(\S+)\s+(on|off)\s+(\S+)\s+(.*)$',line)
            if m:
                self.pseudo.append(dict(name=m.group(1),enabled=(m.group(2)=="on"),ver=m.group(3),desc=m.group(4),raw=line))
        # maps
        self.map_ext={}  # lang -> [ext]
        for fn,txt in self.per.get("list-map-extensions",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            exts=[l.strip() for l in txt.splitlines() if l.strip() and not l.startswith("#")]
            if exts:
                self.map_ext[lang]=exts
        self.map_pat={}
        for fn,txt in self.per.get("list-map-patterns",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            pats=[l.strip() for l in txt.splitlines() if l.strip() and not l.startswith("#")]
            if pats:
                self.map_pat[lang]=pats
        self.map_rex={}
        for fn,txt in self.per.get("list-map-rexprs",{}).items():
            lang=fnmap.get(fn)
            if not lang: continue
            vals=[l for l in txt.splitlines() if l.strip() and not l.startswith("#")]
            if vals:
                self.map_rex[lang]=vals
        # Build ext->lang and pat list preserving language order (?) Maps all order is alphabetical? Languages list order is alphabetical-ish
        # roles per lang
        self.roles={}
        for fn,txt in self.per.get("list-roles",{}).items():
