def process_options_file(state, path, verbose_log, from_config=False, maybe=False):
    # If path is directory, load *.ctags inside sorted
    if os.path.isdir(path):
        files=list_ctags_files_in_dir(path)
        # Also if directory named .ctags.d, its *.ctags already
        # If --options=/tmp/p3 where p3 contains *.ctags files (opts.ctags, my.ctags...) earlier test showed opts loaded (fields=+n and sort=no) - that could be any .ctags in dir sorted.
        for f in files:
            process_options_file(state,f,verbose_log,from_config=from_config,maybe=maybe)
        return
    if not os.path.exists(path):
        if maybe:
            return
        fatal_msg(f'cannot stat "{path}" : No such file or directory')
    # stat error for other?
    try:
        text=open(path,encoding='utf-8',errors='surrogateescape').read()
    except FileNotFoundError:
        if maybe: return
        fatal_msg(f'cannot stat "{path}" : No such file or directory')
    except Exception as e:
        fatal_msg(f'cannot stat "{path}" : {e.strerror if hasattr(e,"strerror") else str(e)}')
    for rawline in text.splitlines():
        line=rawline.strip()
        if not line:
            continue
        # Comment? Lines starting with # ? In my test, # comment line caused (?) maybe ignored as non-option? Let's check: file with "# comment" first line - output warned Ignoring non-option... but that file also had /tmp/... non-option. Need decide: # probably comment ignored silently? We'll treat # as ignored? Search memory: ctags option files allow comments starting with #? Possibly.
        if line.startswith("#"):
            continue
        # If line contains spaces, original: "--sort=no --fields=+n" on one line -> error Invalid value for sort. So treat whole line as one option token.
        if not line.startswith("-"):
            # warning: Ignoring non-option in <path> and a blank line on stderr? Observed:
            # executable: Warning: Ignoring non-option in /tmp/p3/my.ctags
            # (blank line?)
            errline(f"Warning: Ignoring non-option in {path}")
            sys.stderr.write("\n")
            continue
        # process as single arg
        verbose_log.append(f"  Option: {line}\n")
        process_option_tokens(state, [line], verbose_log, in_options_file=True)

