# ---- spec parsing helpers for kinds/fields/extras ----
def parse_spec_tokens(spec):
    """Return list of items: single char or {name}"""
    items=[]
    i=0
    while i<len(spec):
        if spec[i]=='{':
            j=spec.find('}',i)
            if j==-1:
                items.append(spec[i:]); break
            items.append(spec[i:j+1]); i=j+1
        elif spec[i]==',':
            i+=1
        else:
            items.append(spec[i]); i+=1
    return items

