    body=spec
    if spec[0] in '+-':
        op=spec[0]; body=spec[1:]
    else:
        op='set'
    if lang is None:
        # global fields (letters)
        if body=="*":
            all_letters=set(m.fields_by_letter.keys())
            if op=='-':
                state.fields_enabled-=all_letters
            else:
                state.fields_enabled=all_letters if op=='set' else state.fields_enabled|all_letters
            return
        items=parse_spec_tokens(body)
        # For {name} in global? map name to letter if exists
        letters=[]
        for it in items:
            if it.startswith("{"):
                name=it[1:-1]
                found=None
                for l,e in m.fields_by_letter.items():
                    if e['name']==name:
                        found=l; break
                if found:
                    letters.append(found)
                else:
                    warning_msg(state,f"Warning: Unsupported parameter '{{{name}}}' for \"fields\" option")
            elif len(it)==1:
                if it in m.fields_by_letter:
                    letters.append(it)
