                        letters.append(ch)
                    else:
                        warning_msg(state,f"Warning: Unsupported parameter '{ch}' for \"fields\" option")
        if op=='set':
            # fixed fields always? N,F,P,T are fixed yes - in list they stay yes. In tag output, N/F/P not as fields anyway. For set, keep fixed? Check --fields=K output earlier: tags showed only K (no fks). So set replaces non-fixed. But --list-fields with --fields=K would show N etc still yes due fixed.
            new=set(letters)
