                if op=='-':
                    state.lang_fields_enabled[t]=state.lang_fields_enabled.get(t,set())-allnames
                elif op=='set':
                    state.lang_fields_enabled[t]=set(allnames)
                else:
                    state.lang_fields_enabled.setdefault(t,set()).update(allnames)
            return
        items=parse_spec_tokens(body)
        names=[]
        for it in items:
            if it.startswith("{"):
