            elif len(it)==1:
                # error: only long name can be used
                fatal_msg(f"only long name can be used in per language field spec: '{it}'")
            else:
                names.append(it)
        for t in targets:
            valid={e['name'] for e in m.lang_fields.get(t,[])}
            # Also custom fields?
            for nm in names:
                if nm not in valid:
                    # what error? ignore?
                    pass
            cur=state.lang_fields_enabled.setdefault(t,set())
