# ---- language detection ----
def fnmatch_ci(name, pat):
    return fnmatch.fnmatchcase(name, pat)

def detect_language(state, path, content_bytes=None, display_path=None):
    m=meta()
    if state.language_force:
        if state.language_force=="auto":
            pass
        else:
            return state.language_force
    base=os.path.basename(path)
    # rexprs first? RpmMacros pattern (.*/)?macros\.d/macros\.([^/]+)$
    for lang, exprs in state.map_rex.items():
        if lang not in state.enabled_langs and lang not in state.custom_langs:
            continue
        for line in exprs:
            # line format in per file: maybe "<expr>\tsensitive" or just expr? Check captures: list-map-rexprs per lang file lines
            # Our per file stored raw lines; parse first field
            parts=line.split()
            if not parts: continue
            expr=parts[0]
            # Also in caps maprex, expr is second column (?), but per lang likely just expr
            try:
                if re.search(expr, path):
                    return lang
            except:
                pass
    # patterns (fnmatch on basename)
    # Collect candidates: pattern matches take precedence over extension? Need order.
    # We'll check patterns first, in languages order as in list-maps order (which is roughly alphabetical with Unknown first)
    # Use meta languages order
    candidates=[]
    for lang in m.languages:
        if lang not in state.enabled_langs:
            continue
        for pat in state.map_pat.get(lang,[]):
            # pat like "*.abc" or "Makefile.am" or "Kconfig*"
            if fnmatch_ci(base, pat):
                candidates.append(lang); break
    if candidates:
        # If multiple, ? Choose first? But e.g., *.xml pattern for Ant vs extension XML - pattern build.xml only.
        return candidates[0]
    # custom langs patterns
    for lang,info in state.custom_langs.items():
        for pat in info.get('patterns',[]):
            if fnmatch_ci(base, pat):
                return lang
    # extensions
    # extension is after last dot; also some extensions like "build.xml" in map_ext for Ant (treated as extension)
    # Check longest suffix matching: if base endswith "."+ext
    ext_candidates=[]
    for lang in m.languages:
        if lang not in state.enabled_langs:
            continue
        for ext in state.map_ext.get(lang,[]):
            if base.endswith("."+ext):
                ext_candidates.append((len(ext),lang))
                break
    if ext_candidates:
        # If multiple langs share same extension (e.g., *.h C++ vs ... , *.m MatLab vs ObjectiveC?)
        # Original has priority ordering based on parser ??? For .h, expected C++? Let test later. Choose first in languages order among max len?
        # Actually sort by extension length desc, then languages order
        ext_candidates.sort(key=lambda x: (-x[0], m.languages.index(x[1])))
        # Special cases: .h -> C++? According maps, C++ includes *.h, C only *.c, so fine.
        # .py etc unique.
        return ext_candidates[0][1]
    for lang,info in state.custom_langs.items():
        for ext in info.get('extensions',[]):
            if base.endswith("."+ext) or base.endswith(ext) if ext.startswith(".") else base.endswith("."+ext):
                return lang
    # No extension match: try shebang / modeline
    # Need content
    data=None
    if content_bytes is not None:
        data=content_bytes
    else:
        # only read if file exists and is file
        try:
            if os.path.isfile(path):
                data=open(path,'rb').read(8192)
        except:
            data=None
    if data is not None:
        # Determine executable bit
        is_exec=False
        try:
            is_exec=os.access(path, os.X_OK) and os.path.isfile(path)
        except:
            is_exec=False
        # For interactive / stdin content, content_bytes provided and path may not exist; treat shebang eagerly? Probably filename based only.
        # Shebang check if exec or guess_eagerly or content_bytes from interactive? Interactive uses filename extension mainly.
        text_start=data[:4096].decode('utf-8',errors='ignore')
        lines=text_start.splitlines()
        if lines and lines[0].startswith("#!"):
            if is_exec or state.guess_eagerly or content_bytes is not None:
                sb=lines[0][2:].strip()
                # tokens: /usr/bin/env python3 , /bin/bash, etc
                parts=sb.split()
                interp=""
                if parts:
                    first=os.path.basename(parts[0])
                    if first=="env" and len(parts)>1:
                        # skip env options like -S ?
                        idx=1
                        while idx<len(parts) and parts[idx].startswith("-"):
                            idx+=1
                        if idx<len(parts):
                            interp=os.path.basename(parts[idx])
                    else:
                        interp=first
                if interp:
                    # map interp via aliases/shebang_aliases
                    lang=interp_to_lang(state, interp)
                    if lang:
                        return lang
        if state.guess_eagerly:
            # check full content for vim/emacs modelines
            try:
                full=None
                if content_bytes is not None:
                    full=content_bytes.decode('utf-8',errors='ignore')
                elif os.path.isfile(path):
                    full=open(path,'rb').read().decode('utf-8',errors='ignore')
                if full:
                    lang=modeline_to_lang(state, full)
                    if lang:
                        return lang
            except:
                pass
    return None

def interp_to_lang(state, interp):
    m=meta()
    # Direct mapping common
    common={
        'python':'Python','python2':'Python','python3':'Python',
        'sh':'Sh','bash':'Sh','ksh':'Sh','ash':'Sh','dash':'Sh','zsh':'Zsh',
        'perl':'Perl','ruby':'Ruby','node':'JavaScript','nodejs':'JavaScript','js':'JavaScript',
        'php':'PHP','lua':'Lua','awk':'Awk','gawk':'Awk','mawk':'Awk',
        'tclsh':'Tcl','expect':'Tcl','rscript':'R','groovy':'Groovy',
    }
    # strip version numbers python3.10 etc
    base=re.sub(r'[0-9.]+$','',interp)
    if interp in common:
        lang=common[interp]
        if lang in state.enabled_langs:
            return lang
    if base in common:
        lang=common[base]
        if lang in state.enabled_langs:
            return lang
    # Use shebang_aliases patterns: alias may be pattern like python[23]*
    for lang, pats in m.shebang_aliases.items():
        if lang not in state.enabled_langs:
            continue
        for pat in pats:
            # pat could be like "python[23]*"
            if fnmatch.fnmatchcase(interp, pat):
                return lang
            if interp==pat:
                return lang
    # aliases list (language names lower)
    for lang, aliases in state.alias_custom.items():
        if interp in aliases:
            if lang in state.enabled_langs:
                return lang
    # interp equals language name lower?
    c=m.canon(interp)
    if c and c in state.enabled_langs:
        return c
    c=m.canon(base)
    if c and c in state.enabled_langs:
        return c
    return None

def modeline_to_lang(state, text):
    m=meta()
    # vim: set filetype=python:  or vim: syntax=..., ft=
    # search first few and last few lines
    lines=text.splitlines()
    candidates=lines[:5]+lines[-5:] if len(lines)>10 else lines
    ft=None
    for line in candidates:
        mm=re.search(r'vim:.*\b(?:filetype|ft|syntax)\s*=\s*([A-Za-z0-9_+.-]+)',line)
        if mm:
            ft=mm.group(1); break
        mm=re.search(r'-\*-\s*(?:mode:\s*)?([A-Za-z0-9_+.-]+)\s*-\*-',line)
        if mm:
            ft=mm.group(1); break
        mm=re.search(r'-\*-.*\bmode:\s*([A-Za-z0-9_+.-]+)',line)
        if mm:
            ft=mm.group(1); break
    if not ft:
        return None
    # map ft via aliases / language names
    low=ft.lower()
    # aliases custom (from --list-aliases)
    for lang, aliases in meta().aliases.items():
        if low in [a.lower() for a in aliases]:
            if lang in state.enabled_langs:
                return lang
