# ---- Generic brace parser for Java, JavaScript/TypeScript, Go, Rust, PHP, C# ----
def strip_generic_comments(text, line_comment="//", hash_comment=False):
    # reuse C strip but also # for some? For JS/Java/Go/Rust/PHP, // and /* */. PHP also #.
    # Use state machine similar to C
    res=[]; i=0; n=len(text); state='code'
    while i<n:
        c=text[i]; nxt=text[i+1] if i+1<n else ''
        if state=='code':
            if line_comment and c=='/' and nxt=='/':
                state='line'; res.append(' '); res.append(' '); i+=2; continue
            elif hash_comment and c=='#':
                state='line'; res.append(' '); i+=1; continue
            elif c=='/' and nxt=='*':
                state='block'; res.append(' '); res.append(' '); i+=2; continue
            elif c=='"':
                state='string'; res.append('"'); i+=1; continue
            elif c=="'":
                state='char'; res.append("'"); i+=1; continue
            elif c=='`':
                state='template'; res.append('`'); i+=1; continue
            else:
                res.append(c); i+=1; continue
        elif state=='line':
            if c=='\n':
                state='code'; res.append('\n'); i+=1
            else:
                res.append(' '); i+=1
        elif state=='block':
            if c=='*' and nxt=='/':
                state='code'; res.append(' '); res.append(' '); i+=2
            elif c=='\n':
                res.append('\n'); i+=1
            else:
                res.append(' '); i+=1
        elif state in ('string','char','template'):
            quote='"' if state=='string' else "'" if state=='char' else '`'
            if c=='\\' and nxt:
                res.append(' '); res.append(' '); i+=2
            elif c==quote:
                state='code'; res.append(quote); i+=1
            elif c=='\n' and state!='template':
                state='code'; res.append('\n'); i+=1
            else:
                res.append('\n' if c=='\n' else ' '); i+=1
    return ''.join(res)

def parse_java(state, path, display, lines, lang="Java"):
    text="\n".join(lines); clean=strip_generic_comments(text); clines=clean.split("\n")
    tags=[]
    stack=[]  # class/interface/enum contexts with depth
    brace_depth=0; pending=None
    def add(name,idx,kind,scope=None,signature=None,typeref=None,access=None,inherits=None,end=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope:
            t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.typeref=typeref; t.access=access; t.inherits=inherits; t.end_line=end; t.roles="def"
        tags.append(t); return t
    def cur_scope():
        for ctx in reversed(stack):
            if ctx.get('name'):
                return (ctx['kind'],ctx['full'])
        return None
    for idx,cline in enumerate(clines):
        s=cline.strip()
        start_depth=brace_depth
        # class/interface/enum/record
        m=re.search(r'\b(class|interface|enum|record)\s+([A-Za-z_][\w]*)\s*(?:extends\s+([^{]+?))?(?:implements\s+([^{]+?))?(\{|$)',cline)
        if m and not s.startswith("//"):
            kw=m.group(1); name=m.group(2)
            kind={'class':'c','interface':'i','enum':'e','record':'c'}.get(kw,'c')
            inh=None
            parts=[]
            if m.group(3): parts.append(m.group(3).strip())
            if m.group(4): parts.append(m.group(4).strip())
            if parts: inh=", ".join(parts)
            # access
            acc=None
            am=re.search(r'\b(public|private|protected)\b',cline[:m.start()])
            if am: acc=am.group(1)
            t=add(name,idx,kind,scope=cur_scope(),inherits=inh,access=acc)
            full=(cur_scope()[1]+"."+name if cur_scope() else name)
            pending=dict(name=name,full=full,kind=kind,tag=t,typ=kw)
            if '{' not in cline:
                # keep pending for next brace
                pass
            # enum constants on same/next lines handled when in enum?
        elif stack and stack[-1].get('typ')=='enum':
            # enum constants list
            for part in s.rstrip(';').split(","):
                part=part.strip()
                mm=re.match(r'([A-Za-z_][\w]*)',part)
                if mm and part and not part.startswith("}"):
                    add(mm.group(1),idx,'e' if False else 'E',scope=cur_scope())  # Java enum constants kind? check list-kinds Java later: use meta mapping: Java kinds: need lookup
                    # Actually kinds: will be filtered; if kind letter wrong, test fails. We'll lookup later probes.
            # proceed to brace handling
        else:
            # methods/fields inside class, or package/import
            mpkg=re.match(r'\s*package\s+([\w\.]+)\s*;',cline)
            if mpkg:
                add(mpkg.group(1),idx,'p')
            elif stack and stack[-1].get('name'):
                # inside class at its direct depth (brace_depth == stack depth)
                if brace_depth==stack[-1]['depth']:
                    # method: [modifiers] [type] name(params) { or ;
                    # constructor: Name(params) {
                    mm=re.search(r'([A-Za-z_][\w]*)\s*\(([^)]*)\)\s*(\{|;|throws|$)',cline)
                    if mm and '(' in cline:
                        fname=mm.group(1)
                        if fname not in ('if','for','while','switch'):
                            before=cline[:mm.start()].strip()
                            # before may contain modifiers+type, or be modifiers only for constructor
                            # Exclude calls: before empty and not constructor
                            is_ctor=(fname==stack[-1]['name'])
                            if before or is_ctor:
                                # Check suffix or next brace
                                is_def='{' in cline[mm.end():] or mm.group(3)=='{'
                                # look ahead for brace if line ends after )
                                if not is_def and not cline.strip().endswith(";"):
                                    # check next line brace
                                    for j in range(idx+1,min(len(clines),idx+3)):
                                        if clines[j].strip().startswith("{"):
                                            is_def=True; break
                                        if clines[j].strip():
                                            break
                                acc=None
                                am=re.search(r'\b(public|private|protected)\b',before)
                                if am: acc=am.group(1)
                                # kind m for method in Java (list-kinds Java: m methods)
                                add(fname,idx,'m',scope=cur_scope(),signature="("+mm.group(2)+")",access=acc)
                                # pending method block not needed except brace stack generic
                            else:
                                mm=None
                    if not mm or (mm and False):
                        pass
                    # field if not method and ends ;
                    if s.endswith(";") and '(' not in s.split('=')[0]:
                        # parse var similar
                        body=s[:-1].split('=')[0].strip()
                        fm=re.match(r'^(.+?)\s+([A-Za-z_][\w]*)(\s*\[[^\]]*\])?\s*$',body)
                        if fm and len(body.split())>=2:
                            # Ensure not already added as method
                            if not (mm and tags and tags[-1].line_no==idx+1 and tags[-1].kind_letter=='m'):
                                acc=None
                                am=re.search(r'\b(public|private|protected)\b',fm.group(1))
                                if am: acc=am.group(1)
                                add(fm.group(2),idx,'f',scope=cur_scope(),access=acc)
            elif not stack:
                # top-level methods impossible in Java
                pass
        # braces
        for ch in cline:
            if ch=='{':
                brace_depth+=1
                if pending:
                    ctx=dict(pending); ctx['depth']=brace_depth; stack.append(ctx); pending=None
                else:
                    stack.append(dict(name=None,full=None,kind=None,tag=None,depth=brace_depth,typ='block'))
            elif ch=='}':
                if stack:
                    ctx=stack.pop()
                    if ctx.get('tag'):
                        ctx['tag'].end_line=idx+1
                brace_depth=max(0,brace_depth-1)
    for t in tags:
        if t.end_line is None:
            # methods/fields end? Java fields in fields=* maybe no end? Set line for c/i/e/m?
            if t.kind_letter in ('c','i','e'):
                t.end_line=t.line_no
            else:
                t.end_line=None
    return tags

def parse_js(state, path, display, lines, lang="JavaScript"):
    text="\n".join(lines); clean=strip_generic_comments(text); clines=clean.split("\n")
    tags=[]
    stack=[]; brace_depth=0; pending=None
    def add(name,idx,kind,scope=None,signature=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope:
            t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.roles="def"
        tags.append(t); return t
    def cur_scope():
        for ctx in reversed(stack):
            if ctx.get('name'):
                return (ctx['kind'],ctx['full'])
        return None
    for idx,cline in enumerate(clines):
        s=cline.strip()
        # class
        # Note multiple constructs per line: "class Bar { method() {} }"
        # We'll handle class start and then inner method scanning in same line by extracting inside braces
        line_pending=None
        mclass=re.search(r'\bclass\s+([A-Za-z_$][\w$]*)\s*(?:extends\s+([A-Za-z_$][\w$.]*))?\s*\{',cline)
        if mclass:
            name=mclass.group(1)
            t=add(name,idx,'c',scope=cur_scope())
            if mclass.group(2):
                t.inherits=mclass.group(2)
            full=name
            if cur_scope():
                full=cur_scope()[1]+"."+name
            line_pending=dict(name=name,full=full,kind='c',tag=t)
            # scan inside braces for methods on same line after {
            inside=cline[mclass.end():]
            # methods inside: identifier(params) {
            for mm in re.finditer(r'(?:^|[;{}])\s*(?:static\s+|async\s+|get\s+|set\s+)?([A-Za-z_$][\w$]*)\s*\(([^)]*)\)\s*\{',inside):
                mname=mm.group(1)
                if mname in ('if','for','while'): continue
                add(mname,idx,'m',scope=('c',full),signature="("+mm.group(2)+")")
            # Also fields inside single line? rare
        else:
            # function declarations
            mfunc=re.search(r'\bfunction\s*\*?\s+([A-Za-z_$][\w$]*)\s*\(([^)]*)\)',cline)
            if mfunc:
                add(mfunc.group(1),idx,'f',scope=cur_scope(),signature="("+mfunc.group(2)+")")
            else:
                # const/let/var assignment to function/arrow/class etc or plain variable
                mass=re.search(r'\b(const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(.*)',cline)
                if mass and brace_depth== (stack[-1]['depth'] if stack and stack[-1].get('name') else 0) or (mass and not stack):
                    kw=mass.group(1); name=mass.group(2); rhs=mass.group(3).strip()
                    if rhs.startswith("class"):
                        add(name,idx,'c',scope=cur_scope())
                    elif re.match(r'(async\s+)?function\b',rhs) or re.match(r'(async\s*)?\(?[^)]*\)?\s*=>',rhs) or re.match(r'[A-Za-z_$][\w$]*\s*=>',rhs):
                        # extract params
                        sig="()"
                        mm=re.search(r'\(([^)]*)\)\s*=>',rhs)
                        if mm: sig="("+mm.group(1)+")"
                        mm2=re.search(r'function\s*\(([^)]*)\)',rhs)
                        if mm2: sig="("+mm2.group(1)+")"
                        add(name,idx,'f',scope=cur_scope(),signature=sig)
                    else:
                        kind='C' if kw=='const' else 'v'
                        add(name,idx,kind,scope=cur_scope())
                else:
                    # Method inside class (when stack top is class and depth matches)
                    if stack and stack[-1].get('kind')=='c' and brace_depth==stack[-1]['depth']:
                        mm=re.match(r'\s*(?:static\s+|async\s+|get\s+|set\s+)?([A-Za-z_$][\w$]*)\s*\(([^)]*)\)\s*\{',cline)
                        if mm and mm.group(1) not in ('if','for','while','constructor'):
                            # constructor kind? JavaScript kinds: maybe method also for constructor? Keep 'm' for all including constructor? Original might treat constructor as method. Include constructor as m as well - adjust condition
                            add(mm.group(1),idx,'m',scope=cur_scope(),signature="("+mm.group(2)+")")
                        elif mm and mm.group(1)=='constructor':
                            add(mm.group(1),idx,'m',scope=cur_scope(),signature="("+mm.group(2)+")")
                        else:
                            # class field: name = ...; or name;
                            mf=re.match(r'\s*(?:static\s+)?([A-Za-z_$][\w$]*)\s*(=[^;]+)?;',cline)
                            if mf and s.endswith(";") and '(' not in s.split('=')[0]:
                                # JavaScript field kind? Check list kinds: f? Let's assume 'p' property? Need probe. Use 'p' if exists in kinds else 'v'
                                kinds_available=state.kinds_enabled.get(lang,set()) | set(meta().kind_by_letter.get(lang,{}).keys())
                                fk='p' if 'p' in kinds_available else 'v'
                                add(mf.group(1),idx,fk,scope=cur_scope())
                    # Object literal methods / properties: "foo: function() {}", "foo() {}" inside object - skip for now
                    # exports etc ignore
        # brace handling with line_pending for class
        # For single-line class, brace net may be zero: push then pop will set end
        pending_local=line_pending
        for ch in cline:
            if ch=='{':
                brace_depth+=1
                if pending_local:
                    ctx=dict(pending_local); ctx['depth']=brace_depth; stack.append(ctx); pending_local=None
                elif pending:
                    ctx=dict(pending); ctx['depth']=brace_depth; stack.append(ctx); pending=None
                else:
                    stack.append(dict(name=None,full=None,kind=None,tag=None,depth=brace_depth))
            elif ch=='}':
                if stack:
                    ctx=stack.pop()
                    # JS tags in fields=* had no end for functions/classes (foo, Bar etc none). So don't set end_line (keep None)
                brace_depth=max(0,brace_depth-1)
    # JS: end_line should be None for all (observed fields=* no end)
    for t in tags:
        t.end_line=None
    return tags

def parse_go(state, path, display, lines, lang="Go"):
    text="\n".join(lines); clean=strip_generic_comments(text); clines=clean.split("\n")
    tags=[]
    package_name=None
    stack=[]; brace_depth=0; pending=None
    def add(name,idx,kind,scope=None,signature=None,typeref=None,end=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope:
            t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.typeref=typeref; t.roles="def"; t.end_line=end
        tags.append(t); return t
    for idx,cline in enumerate(clines):
        s=cline.strip()
        # package
        mp=re.match(r'^package\s+([A-Za-z_][\w]*)',s)
        if mp:
            package_name=mp.group(1)
            add(package_name,idx,'p')
            # braces none
            continue
        # import (?) single
        # type definitions
        # "type S struct { X int }" or "type S struct {" multi, "type MyInt int", "type I interface { ... }"
        mtype=re.search(r'\btype\s+([A-Za-z_][\w]*)\s+(struct|interface)?\s*(\{)?',cline)
        handled=False
        if mtype and brace_depth==0:
            name=mtype.group(1); kw=mtype.group(2)
            if kw=='struct':
                kind='s'
            elif kw=='interface':
                kind='i'
            else:
                kind='t'
            scope=('p',package_name) if package_name else None
            t=add(name,idx,kind,scope=scope)
            full=f"{package_name}.{name}" if package_name else name
            if kw in ('struct','interface'):
                # members inside same line braces
                mb=re.search(r'\{(.*)\}',cline)
                if mb and mb.group(1).strip():
                    content=mb.group(1).strip()
                    # split by ';' or newline - single line may be "X int" or "X int; Y string"
                    parts=[p.strip() for p in re.split(r'[;\n]',content) if p.strip()]
                    if len(parts)==1 and ',' in content:
                        # "X, Y int" ?
                        pass
                    for part in parts:
                        if kw=='struct':
                            fm=re.match(r'^([A-Za-z_][\w]*)\s+(.+)$',part)
                            if fm:
                                add(fm.group(1),idx,'m',scope=(kind,full),typeref="typename:"+fm.group(2).strip())
                        else:
                            fm=re.match(r'^([A-Za-z_][\w]*)\s*\(([^)]*)\)',part)
                            if fm:
                                add(fm.group(1),idx,'m',scope=(kind,full),signature="("+fm.group(2)+")")
                    t.end_line=idx+1
                elif '{' in cline:
                    pending=dict(name=name,full=full,kind=kind,tag=t,typ=kw)
                else:
                    t.end_line=idx+1
            else:
                t.end_line=idx+1
            handled=True
        # func
        if not handled:
            mfunc=re.search(r'\bfunc\s+(?:\(([^)]*)\)\s*)?([A-Za-z_][\w]*)\s*\(([^)]*)\)',cline)
            if mfunc and brace_depth==0:
                recv=mfunc.group(1); name=mfunc.group(2); params=mfunc.group(3)
                if recv:
                    # method: receiver type last word strip *
                    recv_parts=recv.strip().split()
                    rtype=recv_parts[-1].lstrip('*') if recv_parts else ""
                    scope_kind='s'  # ? Scope kind name for method receivers is struct? Check fields Go method later - we treat scope as struct:Recv
                    # Kind for Go methods: list kinds Go: f func, maybe? Check meta: Go kinds include ... We'll use 'f' ??? Original hello go only func main kind f (letter f shown as 'f' but kind name "func"). For methods, maybe 'f' also with scope type?
                    # Use scope ( 't'? ) We'll set scope_kind_name manually to "struct" if receiver is struct type unknown.
                    t=add(name,idx,'f',scope=(scope_kind,f"{package_name}.{rtype}" if package_name else rtype),signature="("+params+")")
                else:
                    scope=('p',package_name) if package_name else None
                    t=add(name,idx,'f',scope=scope,signature="("+params+")")
                # end line when brace closes: track pending func for brace stack to set end? Go f/s had end in fields=*
                if '{' in cline:
                    pending=dict(name=name,full=name,kind='f',tag=t,typ='func')
                else:
                    # maybe interface method signature etc not here
                    t.end_line=idx+1
                handled=True
        # var/const at top level
        if not handled and brace_depth==0:
            mv=re.match(r'^(var|const)\s+([A-Za-z_][\w]*)\b',s)
            if mv:
                kind='v' if mv.group(1)=='var' else 'c'
                scope=('p',package_name) if package_name else None
                add(mv.group(2),idx,kind,scope=scope)
                handled=True
        # Members of struct/interface multiline
        if stack and stack[-1].get('typ') in ('struct','interface') and not handled:
            ctx=stack[-1]
            if ctx['typ']=='struct':
                fm=re.match(r'^\s*([A-Za-z_][\w]*)\s+(.+?)\s*$',cline)
                if fm and s and not s.startswith("}"):
                    # remove tag literal `...`
                    typ=re.sub(r'`[^`]*`','',fm.group(2)).strip()
                    add(fm.group(1),idx,'m',scope=(ctx['kind'],ctx['full']),typeref="typename:"+typ)
            else:
                fm=re.match(r'^\s*([A-Za-z_][\w]*)\s*\(([^)]*)\)',cline)
                if fm:
                    add(fm.group(1),idx,'m',scope=(ctx['kind'],ctx['full']),signature="("+fm.group(2)+")")
        # braces
        for ch in cline:
            if ch=='{':
                brace_depth+=1
                if pending:
                    ctx=dict(pending); ctx['depth']=brace_depth; stack.append(ctx); pending=None
                else:
                    stack.append(dict(name=None,full=None,kind=None,tag=None,depth=brace_depth,typ='block'))
            elif ch=='}':
                if stack:
                    ctx=stack.pop()
                    if ctx.get('tag') and ctx['tag'].end_line is None:
                        ctx['tag'].end_line=idx+1
                brace_depth=max(0,brace_depth-1)
    for t in tags:
        if t.kind_letter=='p':
            t.end_line=None
        if t.kind_letter in ('m','v','c','t'):
            # Go member had no end in fields=* (X line no end), var maybe?
            if t.kind_letter=='m':
                t.end_line=None
    return tags

def parse_rust(state, path, display, lines, lang="Rust"):
    text="\n".join(lines); clean=strip_generic_comments(text); clines=clean.split("\n")
    tags=[]
    stack=[]; brace_depth=0; pending=None
    def add(name,idx,kind,scope=None,signature=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope:
            t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.roles="def"
        tags.append(t); return t
    def cur_scope():
        for ctx in reversed(stack):
            if ctx.get('name'):
                return (ctx['kind'],ctx['full'])
        return None
    for idx,cline in enumerate(clines):
        s=cline.strip()
        line_pending=None
        # impl
        mimpl=re.search(r'\bimpl\s+(?:[A-Za-z_][\w]*\s+for\s+)?([A-Za-z_][\w]*)\s*\{?',cline)
        # But need ensure "impl Foo {" - group is Foo; "impl Trait for Foo" kind implementation name is Foo? For hello, impl Foo tag Foo kind c (implementation)
        # Rust kinds: c implementation (? letter c in output for impl Foo: kind name implementation, letter c?) In default output Foo impl kind 'c' ; method kind 'P' (method?) Output: method kind P, scope implementation:Foo. Wait list-kinds Rust check.
        # We'll use letters from observations: impl 'c', method in impl 'P', struct 's', field 'm' (kind field but letter m?), function 'f'
        # Check meta later.
        handled_impl=False
        if re.search(r'^\s*(pub\s+)?impl\b',cline):
            m=mimpl
            if m:
                name=m.group(1)
                # For "impl Trait for Type", name group above captures Trait? pattern: (?:Trait for)? Our regex: impl\s+(?:X for )? (Y) -> inner non-capturing with \s+for\s+ needs second? It will capture correctly in many cases.
                t=add(name,idx,'c',scope=cur_scope())
                line_pending=dict(name=name,full=name,kind='c',tag=t,typ='impl')
                handled_impl=True
                # methods on same line inside {}
                inside=cline[m.end():] if m.end() < len(cline) else ""
                for mm in re.finditer(r'\bfn\s+([A-Za-z_][\w]*)\s*\(([^)]*)\)',cline):
                    # skip if this fn is... it's method
                    add(mm.group(1),idx,'P',scope=('c',name),signature="("+mm.group(2)+")")
        # struct/enum/trait/mod/type/const/static
        if not handled_impl:
            mm=re.search(r'\b(struct|enum|trait|mod|type)\s+([A-Za-z_][\w]*)\s*(\{|;|\(|=)?',cline)
            if mm and brace_depth==(stack[-1]['depth'] if stack and stack[-1].get('name') else 0) or (mm and not stack):
                kw=mm.group(1); name=mm.group(2)
                kindmap={'struct':'s','enum':'g','trait':'t','mod':'m','type':'T'}
                # Check Rust kind letters from meta: need correct mapping; we will lookup by name in meta kind_by_name
                # Instead dynamic: find kind by name keyword mapping semantic names
                # struct -> struct, enum -> enum, trait -> trait/interface?, mod -> module, type -> typedef?
                kind=kindmap.get(kw,'s')
                # Try resolve via meta names
                namemap={'struct':'struct','enum':'enum','trait':'trait','mod':'module','type':'typedef'}
                kbyname=meta().kind_by_name.get(lang,{})
                if namemap.get(kw) in kbyname:
                    kind=kbyname[namemap[kw]]['letter']
                t=add(name,idx,kind,scope=cur_scope())
                line_pending=dict(name=name,full=name,kind=kind,tag=t,typ=kw)
                # struct fields same line
                if kw=='struct':
                    mb=re.search(r'\{(.*)\}',cline)
                    if mb and mb.group(1).strip():
                        for part in mb.group(1).split(","):
                            part=part.strip()
                            fm=re.match(r'^(?:pub\s+)?([A-Za-z_][\w]*)\s*:',part)
                            if fm:
                                # field kind: letter m but name 'field' in fields=*
                                fkind='m'
                                if 'field' in kbyname:
                                    fkind=kbyname['field']['letter']
                                add(fm.group(1),idx,fkind,scope=(kind,name))
                        line_pending=None  # closes same line if } present
                    elif '{' not in cline:
                        line_pending=None
                if kw=='enum':
                    mb=re.search(r'\{(.*)\}',cline)
                    if mb and mb.group(1).strip():
                        for part in mb.group(1).split(","):
                            part=part.strip()
                            em=re.match(r'^([A-Za-z_][\w]*)',part)
                            if em:
                                ekind='e'
                                if 'enumerator' in kbyname: ekind=kbyname['enumerator']['letter']
                                add(em.group(1),idx,ekind,scope=(kind,name))
                        line_pending=None
                handled_impl=False  # allow brace handling with pending below
                pending=line_pending
                line_pending=None
            else:
                # fn
                mfn=re.search(r'\bfn\s+([A-Za-z_][\w]*)\s*(?:<[^>]*>)?\s*\(([^)]*)\)',cline)
                if mfn:
                    # if inside impl/trait, method
                    if stack and stack[-1].get('typ') in ('impl','trait'):
                        kbyname=meta().kind_by_name.get(lang,{})
                        mkind='P' if 'method' not in kbyname else kbyname['method']['letter']
                        add(mfn.group(1),idx,mkind,scope=cur_scope(),signature="("+mfn.group(2)+")")
                    elif not (stack and stack[-1].get('typ')=='impl'):
                        # avoid double counting fn inside impl same line handled above; here stack not yet pushed for single line impl, handled_impl would be True so not here
                        add(mfn.group(1),idx,'f',scope=cur_scope(),signature="("+mfn.group(2)+")")
                else:
                    # const/static
                    mc=re.search(r'\b(const|static)\s+(?:mut\s+)?([A-Za-z_][\w]*)\s*:',cline)
                    if mc and brace_depth==0:
                        kind='C' if mc.group(1)=='const' else 'v'
                        add(mc.group(2),idx,kind,scope=cur_scope())
                    # struct fields multi-line
                    if stack and stack[-1].get('typ')=='struct':
                        fm=re.match(r'\s*(?:pub\s+)?([A-Za-z_][\w]*)\s*:',cline)
                        if fm:
                            kbyname=meta().kind_by_name.get(lang,{})
                            fkind=kbyname['field']['letter'] if 'field' in kbyname else 'm'
                            add(fm.group(1),idx,fkind,scope=cur_scope())
                    if stack and stack[-1].get('typ')=='enum':
                        fm=re.match(r'\s*([A-Z][\w]*)',cline)
                        if fm and s and not s.startswith("}"):
                            kbyname=meta().kind_by_name.get(lang,{})
                            ekind=kbyname['enumerator']['letter'] if 'enumerator' in kbyname else 'e'
                            add(fm.group(1),idx,ekind,scope=cur_scope())
        # braces, using line_pending if handled_impl else pending
        active_pending=line_pending if line_pending else pending
        # if struct pending set above, active_pending is pending var
        for ch in cline:
            if ch=='{':
                brace_depth+=1
                if active_pending:
                    ctx=dict(active_pending); ctx['depth']=brace_depth; stack.append(ctx); active_pending=None; pending=None
                else:
                    stack.append(dict(name=None,full=None,kind=None,tag=None,depth=brace_depth,typ='block'))
            elif ch=='}':
                if stack:
                    stack.pop()
                brace_depth=max(0,brace_depth-1)
        pending=active_pending
    for t in tags:
        t.end_line=None
    return tags

def parse_php(state, path, display, lines, lang="PHP"):
    text="\n".join(lines); clean=strip_generic_comments(text,hash_comment=True); clines=clean.split("\n")
    tags=[]; stack=[]; brace_depth=0; pending=None
    def add(name,idx,kind,scope=None,signature=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope:
            t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.roles="def"; tags.append(t); return t
    def cur():
        for c in reversed(stack):
            if c.get('name'): return (c['kind'],c['full'])
        return None
    for idx,cline in enumerate(clines):
        line_pending=None
        mc=re.search(r'\b(class|interface|trait)\s+([A-Za-z_][\w]*)\s*(?:extends\s+([A-Za-z_][\w\\]*))?(?:implements\s+([^{]+))?\{?',cline)
        if mc:
            kw=mc.group(1); name=mc.group(2); kind={'class':'c','interface':'i','trait':'t'}.get(kw,'c')
            t=add(name,idx,kind,scope=cur())
            if mc.group(3): t.inherits=mc.group(3)
            line_pending=dict(name=name,full=name,kind=kind,tag=t)
        else:
            mf=re.search(r'\bfunction\s+([A-Za-z_][\w]*)\s*\(([^)]*)\)',cline)
            if mf:
                add(mf.group(1),idx,'f',scope=cur(),signature="("+mf.group(2)+")")
