def format_tag_xref(state, tag, display_path):
    # Use xformat string default "%-16N %-10K %4n %-16F %C"
    fmt=state.xformat
    # Parse percent specs: %[-][width]<letter> . Letters are field letters (list-fields). Also %% ?
    out=""
    i=0
    while i<len(fmt):
        if fmt[i]=='%' and i+1<len(fmt):
            j=i+1
            # parse flags: - etc and width digits
            spec=""
            # collect until letter (single char that is field letter)
            # format spec like %-16N, %4n, %10l etc.
            start=j
            # flags/width chars are -.0123456789
            while j<len(fmt) and fmt[j] in "-0123456789.":
                j+=1
            if j>=len(fmt):
                out+=fmt[i:]; break
            field_letter=fmt[j]
            width_spec=fmt[start:j]  # e.g., -16 or 4 or 10
            # get value
            val=get_field_value(state, tag, field_letter)
            if val is None:
                val=""
            else:
                val=str(val)
            # Special handling: F in xref should be display_path (not tag.path raw if relative conversion done caller passes display). get_field_value for F returns tag.path which is original display before relative conversion? tag.path is display passed at parse time (input path as given). Relative conversion for xref??? Xref ignores tagfile location, so path as given is fine. But if caller adjusted display_path for tag-relative, xref probably still input path? Using display_path for F:
            if field_letter=='F':
                val=display_path
            if field_letter=='C':
                val=(tag.line_text.strip() if tag.line_text else "")
            # Apply formatting using Python's % formatting equivalent: construct format string "%<width>s"
            if width_spec:
                # Python: %-16s, %4s etc. For numbers %4n where val is numeric string, original %4n aligns right as integer ("   9"). Using %4s gives same for single digit? "   9" yes.
                pyfmt="%"+width_spec+"s"
                try:
                    val=pyfmt % val
                except:
                    pass
            out+=val
            i=j+1
        elif fmt[i]=='%' and i+1<len(fmt) and fmt[i+1]=='%':
            out+="%"; i+=2
        else:
            out+=fmt[i]; i+=1
    return out.rstrip("\n")

def format_etags_section(state, tags_by_file):
    # tags_by_file: list of (display_path_original_input, tags list, file_bytes_for_offsets, lines)
    # Output bytes? etags format uses \f\n filename,size\n then lines: "<line text>\x7f<name>\x01<line>,<byte_offset>\n"
    # Size = total bytes of tag lines section for file (?) In earlier example /tmp/p2/c.c,625 - sum of lengths of following lines (including newline?) Let's verify: section content lines each ?
    # We'll compute lines first then size = sum(len(line.encode + newline))
    out_parts=[]
    for display, tags, data_bytes, lines in tags_by_file:
        # compute byte offset per line: offset of start of line in file (bytes)
        offsets=[]
        if data_bytes is not None:
            # split bytes by \n
            pos=0
            # lines as decoded split loses byte lengths for non-utf8 maybe approximate encode
            # Better compute from data_bytes split
            blines=data_bytes.split(b'\n')
            off=0
            for bl in blines:
                offsets.append(off)
                off+=len(bl)+1
        section_lines=[]
        for t in tags:
            ln_idx=t.line_no-1
            linetext=lines[ln_idx] if 0<=ln_idx<len(lines) else t.pattern_line
            offset=offsets[ln_idx] if 0<=ln_idx<len(offsets) else 0
            section_lines.append(f"{linetext}\x7f{t.name}\x01{t.line_no},{offset}\n")
        size=sum(len(s.encode('utf-8','surrogateescape')) for s in section_lines)
        out_parts.append(f"\f\n{display},{size}\n")
        out_parts.extend(section_lines)
    # etags include files at end
    for inc in state.etags_include:
        out_parts.append(f"\f\n{inc},include\n")
    return "".join(out_parts)

