def base_line_patch(line,start,end,new):
    # Replace token at [start:end] with new padded to same width if shorter, or if longer (no->yes) it will shift columns by 1? Original column width for ENABLED is maybe 8 chars ("yes     " / "no      "). Replacing "no" with "yes" should keep following column aligned: token field width including trailing spaces until next token. Our start-end only covers token, next char is space; replacing "no" (2) with "yes" (3) inserts 1 extra char shifting rest by 1, breaking alignment. So need consume one trailing space when expanding, add one when shrinking.
    if len(new)<(end-start):
        return line[:start]+new+" "*(end-start-len(new))+line[end:]
    elif len(new)>(end-start):
        extra=len(new)-(end-start)
        # remove extra spaces after token if present
        suffix=line[end:]
        if suffix.startswith(" "*extra):
            suffix=suffix[extra:]
        return line[:start]+new+suffix
    else:
        return line[:start]+new+line[end:]

