            out_write(txt); return 0
        out_write(m.caps.get("roles","")); return 0
    # parse lang and kindspec
    # arg examples: "C", "C.*", "C.f", "C.{function}", "C.{header}d" (multiple)
    # Split at first '.' but lang names contain no dot except? C++ etc fine. Lang 'C#' etc.
    # Find lang prefix: try longest language name that matches prefix before dot
    lang=None; kindspec=None
    # If arg contains ".", split
    if "." in arg:
        # lang could be "C" and rest ".{...}"
        idx=arg.find(".")
        cand=arg[:idx]; rest=arg[idx+1:]
        c=m.canon(cand)
        if c:
            lang=c; kindspec=rest
        else:
            # maybe lang name includes ??? fallback treat whole as lang
            lang=None
    if lang is None:
        c=m.canon(arg)
        if not c:
            fatal_msg(f'Unknown language "{arg}" in "list-roles" option')
        lang=c; kindspec=None
    fn=m.filename_for(lang); base=m.per.get("list-roles",{}).get(fn,"")
    if kindspec is None or kindspec=="*":
        txt=base
    else:
        # Filter kinds: kindspec tokens are letters/names in {} or single letters concatenated
        letters=set()
        i=0
        while i<len(kindspec):
            if kindspec[i]=='{':
                j=kindspec.find('}',i); nm=kindspec[i+1:j]; e=m.kind_by_name.get(lang,{}).get(nm)
                if e: letters.add(e['letter'])
                i=j+1
            elif kindspec[i]=='*':
                letters=None; break
            else:
                letters.add(kindspec[i]); i+=1
        lines=[]
        for line in base.splitlines():
            if line.startswith("#"):
                lines.append(line); continue
            mm=re.match(r'^(\S+)/',line.strip())
            if mm and letters and mm.group(1) not in letters:
                continue
            lines.append(line)
        txt="\n".join(lines)+"\n" if lines else ""
