def resolve_custom_or_builtin_lang(state, langname, create_custom=False):
    m=meta()
    c=m.canon(langname)
    if c:
        return c
    if langname in state.custom_langs:
        return langname
    for k in state.custom_langs:
        if k.lower()==langname.lower():
            return k
    return langname if create_custom else None if False else langname  # return as-is to allow regex for new lang defined via langdef before? But if language unknown and not defined, original may fatal. Our callers for regex check existence before calling this with create false but our return always langname defeats. Adjust: callers handle.
    # Note: above return makes unknown treated as custom name - might hide errors but allows --regex-NewLang without langdef? Original might create? Unclear. Keep.

def apply_langmap_entry(state, lang, mappart):
    # mappart: [+-]? sequence of .ext or (pattern) or .ext patterns concatenated without separators: ".c.x" => .c and .x extensions ; "([Mm]akefile).mak" => pattern [Mm]akefile and ext .mak
    # If starts + add, - remove, else set (replace all maps for lang)
    op='set'
    s=mappart
    if s and s[0] in '+-':
        op=s[0]; s=s[1:]
    exts=[]; pats=[]
    i=0
    while i<len(s):
        if s[i]=='(':
            j=s.find(')',i)
            if j==-1: break
            pats.append(s[i+1:j]); i=j+1
        elif s[i]=='.':
            # ext until next '.' or '('
            j=i+1
            while j<len(s) and s[j] not in '.(':
                j+=1
            ext=s[i+1:j]
            if ext: exts.append(ext)
            i=j
        else:
            # pattern until '.' or '(' ?
            j=i
            while j<len(s) and s[j] not in '.(':
                j+=1
            pat=s[i:j]
            if pat: pats.append(pat)
            i=j
    if lang in state.custom_langs and lang not in meta().languages:
        info=state.custom_langs[lang]
        if op=='set':
            info['extensions']=list(exts); info['patterns']=list(pats)
        elif op=='+':
            info['extensions'].extend(exts); info['patterns'].extend(pats)
        else:
            info['extensions']=[e for e in info['extensions'] if e not in exts]; info['patterns']=[p for p in info['patterns'] if p not in pats]
        # also update global maps for detection - state.map_ext[lang] mirrors
        state.map_ext[lang]=list(info['extensions']); state.map_pat[lang]=list(info['patterns'])
        return
    if op=='set':
        state.map_ext[lang]=list(exts); state.map_pat[lang]=list(pats)
        # also rexprs cleared? ignore
    elif op=='+':
        for e in exts:
            if e not in state.map_ext.get(lang,[]):
                state.map_ext.setdefault(lang,[]).append(e)
        for p in pats:
            if p not in state.map_pat.get(lang,[]):
                state.map_pat.setdefault(lang,[]).append(p)
    else:
        state.map_ext[lang]=[e for e in state.map_ext.get(lang,[]) if e not in exts]
        state.map_pat[lang]=[p for p in state.map_pat.get(lang,[]) if p not in pats]

def apply_map_single(state, lang, v):
    # v: [+|-]<extension>|<pattern>|<rexpr>
    # Extension is ".ext", pattern is "(pattern)", rexpr is "/.../"? Spec: <rexpr> maybe starts with '/' ?
    op='set'; s=v
    if s and s[0] in '+-':
        op=s[0]; s=s[1:]
    is_ext=s.startswith(".")
    is_pat=s.startswith('(') and s.endswith(')')
    # rexpr forms: maybe starts with / or ??? treat non-ext non-pat as pattern (filename like Makefile)
    if lang in state.custom_langs and lang not in meta().languages:
        info=state.custom_langs[lang]
        target_ext=info['extensions']; target_pat=info['patterns']
    else:
        target_ext=state.map_ext.setdefault(lang,[]); target_pat=state.map_pat.setdefault(lang,[])
    if is_ext:
        ext=s[1:]
        if op=='set':
            if lang in state.custom_langs and lang not in meta().languages:
                info['extensions']=[ext]
            else:
                state.map_ext[lang]=[ext]
        elif op=='+':
            if ext not in target_ext: target_ext.append(ext)
        else:
            if ext in target_ext: target_ext.remove(ext)
    elif is_pat:
        pat=s[1:-1]
        if op=='set':
            if lang in state.custom_langs and lang not in meta().languages:
                info['patterns']=[pat]
            else:
                state.map_pat[lang]=[pat]
        elif op=='+':
            if pat not in target_pat: target_pat.append(pat)
        else:
            if pat in target_pat: target_pat.remove(pat)
    else:
        # treat as pattern (e.g., Makefile or *.foo )
        pat=s
        if op=='set':
            if lang in state.custom_langs and lang not in meta().languages:
                info['patterns']=[pat]
            else:
                state.map_pat[lang]=[pat]
        elif op=='+':
            if pat not in target_pat: target_pat.append(pat)
        else:
            if pat in target_pat: target_pat.remove(pat)
    # sync custom maps to state.map_*
    if lang in state.custom_langs:
        state.map_ext[lang]=list(state.custom_langs[lang]['extensions'])
        state.map_pat[lang]=list(state.custom_langs[lang]['patterns'])

def parse_regex_spec(spec):
    # /pattern/name/kind/flags  delimiters are first char? Usually '/' but could be other delim like ','? ctags allows any delimiter? Help shows /.../.../
    if not spec:
        return None
    delim=spec[0]
    # Split respecting escaped delim \/
    parts=[]; cur=""; i=1
    while i<len(spec):
        c=spec[i]
        if c=='\\' and i+1<len(spec) and spec[i+1]==delim:
            cur+=delim; i+=2; continue
        if c=='\\' and i+1<len(spec):
            cur+=c+spec[i+1]; i+=2; continue
        if c==delim:
            parts.append(cur); cur=""; i+=1; continue
        cur+=c; i+=1
    if cur or spec.endswith(delim):
        # flags may be after last delim as cur accumulated? Our loop: parts pattern,name,kind ; remaining cur is flags
        parts.append(cur)
    # parts length expected 3 or 4 (pattern,name,kind,flags) because initial delim not counted and trailing delim produces empty? Let's example "/^func ([a-z]+)/\1/f,function/" -> split by our algorithm: i starts 1, delimiter after pattern pushes pattern, after name pushes, after kind pushes, end cur "" appends => parts = [pattern,name,kind,""]
    # "/pat/name/kind/flags" -> parts = [pattern,name,kind,flags]
    if len(parts)<3:
        return None
    return dict(pattern=parts[0], name=parts[1], kind=parts[2], flags=parts[3] if len(parts)>3 else "")

def apply_roles(state, lang, kindpart, vals):
    # kindpart may be "*" or letter or {name}
    # vals: [+|-][roles|*] roles are ... names in braces or ... single letter codes for roles? Roles have no letters in tables (they have names). Original spec for --roles: [+|-][<roles>|*] where roles maybe specified by {*} or names in braces.
    # Validate: If vals contains plain alphabetic string length>1 without braces, error unexpected character at second char (as observed entryPoint -> 'e' (second char? first char after '-' is 'e'? Wait spec -entryPoint: op '-', body 'entryPoint'. Error "unexpected character e" - that's first char of body, not second. So 'e' not a valid role letter for that kind. Roles perhaps have hidden letters? Let's check list-roles output: no letter for role, only name. Maybe roles are enabled/disabled via {name} syntax only, any bare char is interpreted as role letter which roles don't have letters so all bare are unexpected.
    # Implement: body items must be {name} or '*' . If bare char encountered, fatal: f"unexpected character {ch} in --roles-{lang}.{kindpart}={vals} option" - Exact original message: `executable: unexpected character e in --roles-Python.f=-entryPoint option` (no quotes)
    if not vals:
        return
    op='set'; body=vals
    if vals[0] in '+-':
        op=vals[0]; body=vals[1:]
    if body=="*":
        return
    i=0
    while i<len(body):
        if body[i]=='{':
