def apply_langmap_entry(state, lang, mappart):
    # mappart: [+-]? sequence of .ext or (pattern) or .ext patterns concatenated without separators: ".c.x" => .c and .x extensions ; "([Mm]akefile).mak" => pattern [Mm]akefile and ext .mak
    # If starts + add, - remove, else set (replace all maps for lang)
    op='set'
    s=mappart
    if s and s[0] in '+-':
        op=s[0]; s=s[1:]
    exts=[]; pats=[]
    i=0
    while i<len(s):
        if s[i]=='(':
            j=s.find(')',i)
            if j==-1: break
            pats.append(s[i+1:j]); i=j+1
        elif s[i]=='.':
            # ext until next '.' or '('
            j=i+1
            while j<len(s) and s[j] not in '.(':
                j+=1
            ext=s[i+1:j]
            if ext: exts.append(ext)
            i=j
        else:
            # pattern until '.' or '(' ?
            j=i
            while j<len(s) and s[j] not in '.(':
                j+=1
            pat=s[i:j]
            if pat: pats.append(pat)
            i=j
