    pats=DEFAULT_EXCLUDES+state.excludes
    base=name
    excluded=False
    for p in pats:
        # pattern matching: fnmatch on basename (and maybe full? exclude=sub matched directory named sub anywhere) Using fnmatchcase on base; also if pattern contains '/' match fullpath?
        if fnmatch.fnmatchcase(base,p):
