def is_excluded(state, name, is_dir=False, fullpath=""):
    # Default excludes list from --list-excludes + user excludes. Exceptions override.
    DEFAULT_EXCLUDES=['*.a','*.class','*.dll','*.exe','*.gcda','*.gcno','*.lib','*.o','*.obj','*.pyc','*.pyo','*.so','*~','.*.swp','.DS_Store','.arch-ids','.arch-inventory','.bzr','.bzrignore','.cvsignore','.deps','.dvi','.git','.gitattributes','.gitignore','.hg','.hgignore','.svn','BitKeeper','CVS','EIFGEN','PENDING','RCS','RESYNC','SCCS','_darcs','autom4te.cache','{arch}']
    pats=DEFAULT_EXCLUDES+state.excludes
    base=name
    excluded=False
    for p in pats:
        # pattern matching: fnmatch on basename (and maybe full? exclude=sub matched directory named sub anywhere) Using fnmatchcase on base; also if pattern contains '/' match fullpath?
        if fnmatch.fnmatchcase(base,p):
            excluded=True; break
        if '/' in p and fnmatch.fnmatchcase(fullpath,p):
            excluded=True; break
    if excluded:
        for ep in state.exclude_exceptions:
            if fnmatch.fnmatchcase(base,ep) or ('/' in ep and fnmatch.fnmatchcase(fullpath,ep)):
                return False
        return True
    return False

def collect_input_files(state):
    files=[]
    # -L files
    for lf in state.list_files:
        if lf=="-":
            data=sys.stdin.read().splitlines()
            for line in data:
                line=line.strip()
                if line:
                    files.append(line)
        else:
            if not os.path.exists(lf):
                errline(f'Warning: cannot open input file "{lf}" : No such file or directory')
                continue
            try:
                for line in open(lf,encoding='utf-8',errors='surrogateescape'):
                    line=line.strip()
                    if line:
                        files.append(line)
            except Exception as e:
                errline(f'Warning: cannot open input file "{lf}" : {e.strerror if hasattr(e,"strerror") else str(e)}')
    files.extend(state.files)
    # Expansion directories/files etc will be done in processing order with warnings. Return raw list; expansion happens per entry to preserve warning order and recurse ordering.
    return files

