def gather_dir(state, dirpath, out, depth):
    if state.maxdepth is not None and depth>state.maxdepth:
        return
    try:
        entries=list(os.scandir(dirpath))
    except:
        return
    entries_sorted=sorted(entries, key=lambda e: e.name)
    for e in entries_sorted:
        if is_excluded(state, e.name, is_dir=e.is_dir(follow_symlinks=state.links), fullpath=e.path):
            continue
        # links handling
        if e.is_symlink() and not state.links:
            # If links=no, skip symlink files/dirs? For regular symlink to file given explicitly, maybe skip during recurse.
            continue
        if e.is_dir(follow_symlinks=state.links):
            if state.maxdepth is None or depth < state.maxdepth:
                gather_dir(state, e.path, out, depth+1)
            # if depth == maxdepth, do not recurse into subdir (files inside beyond)
            # But need include files in current dir: they are gathered when depth is level of dirpath. Our call started depth=1 for top dir; subdir files depth 2...
        elif e.is_file(follow_symlinks=state.links):
            out.append(e.path)

