def sort_tag_lines(lines, sort_mode):
    # lines are formatted strings without newline. For formats where sorting is applied to tag lines (u-ctags/e-ctags/json/xref/etags?) Sorting applies for tags/json/xref but not etags? etags section tags were file order (Zebra, apple...) even default sort=yes? In etags example with -e, Python tags order was file order, not sorted. So etags ignores sort? For JSON default sorted, sorting applied. Xref sorted as well.
    # For lines sorting, original used external sort (?) with LC_COLLATE C? Dedup exact duplicates for sorted modes.
    # For pseudo lines + tag lines sorted together as entire file lines.
    if sort_mode=="yes":
        sorted_lines=sorted(lines)  # Python unicode codepoint sort approximates byte sort for ASCII/UTF8
        dedup=[]
        prev=None
        for l in sorted_lines:
            if l!=prev:
                dedup.append(l); prev=l
        return dedup
    elif sort_mode=="foldcase":
        sorted_lines=sorted(lines, key=lambda s: s.lower())
        # Dedup case-insensitive for identical after folding? But earlier x1/x2 with Apple/apple different paths both remained (their folded lines differ by path/pattern case). For same file Apple/apple, folded lines are: "apple\t/tmp/.../^def apple..." vs "apple\t/tmp/.../^def apple..." ignoring case pattern also lowercased -> lines become equal(?) Apple line pattern "def Apple" lower becomes def apple - so folded comparison equates them, and dedup after foldcase sort removes one (the later?). Stable sort preserves original order apple (line2) before Apple (line3) when folded equal, dedup by folded equality keeps first = apple. That matches.
        dedup=[]; prev_fold=None
        for l in sorted_lines:
            f=l.lower()
            if f!=prev_fold:
                dedup.append(l); prev_fold=f
            # else drop duplicate folded
        return dedup
    else:
        return lines

