        lines=[l for l in lines if not l.startswith("!_")]
        content_append="\n".join(lines)+("\n" if lines else "")
        data=content_append.encode('utf-8','surrogateescape') if not enc else content_append.encode(enc,errors='replace')
    with open(tagfile_path,mode) as f:
        f.write(data)

