def flags_to_machinable(txt):
    out=[]
    for line in txt.splitlines():
        if line.startswith("#"):
            parts=line.lstrip("#").split(); out.append("#"+"\t".join(parts)); continue
        mm=re.match(r'^(\S+)\s+(\S+)\s+(.*)$',line)
        if mm:
            out.append("\t".join(mm.groups()))
        else:
            out.append(line)
    return "\n".join(out)+"\n"

