def parse_iniconf(state,path,display,lines,lang="Iniconf"):
    tags=[]; section=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        m=re.match(r'\[([^\]]+)\]',s)
        if m:
            section=m.group(1); t=Tag(section,display,idx+1,raw,'s',lang); t.roles="def"; tags.append(t); continue
        mk=re.match(r'^([A-Za-z0-9_.-]+)\s*=',s)
        if mk:
            t=Tag(mk.group(1),display,idx+1,raw,'k',lang); t.roles="def"
            if section: t.scope_kind_letter='s'; t.scope_name=section
            tags.append(t)
    return tags

def parse_erlang(state,path,display,lines,lang="Erlang"):
    tags=[]; mod=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mm=re.match(r'-module\((\w+)\)\.',s)
        if mm: mod=mm.group(1); t=Tag(mod,display,idx+1,raw,'m',lang); t.roles="def"; tags.append(t); continue
        mr=re.match(r'-record\((\w+),',s)
        if mr: t=Tag(mr.group(1),display,idx+1,raw,'r',lang); t.roles="def"; tags.append(t); continue
        md=re.match(r'-define\((\w+),',s)
        if md: t=Tag(md.group(1),display,idx+1,raw,'d',lang); t.roles="def"; tags.append(t); continue
        mf=re.match(r'^([a-z][\w]*)\s*\(([^)]*)\)\s*->',s)
        if mf:
            t=Tag(mf.group(1),display,idx+1,raw,'f',lang); t.roles="def"
            if mod: t.scope_kind_letter='m'; t.scope_name=mod
            tags.append(t)
    return tags

def parse_elixir(state,path,display,lines,lang="Elixir"):
    tags=[]; stack=[]
    for idx,raw in enumerate(lines):
        s=raw.strip()
        if s=="end":
            if stack: stack.pop()
            continue
        mm=re.match(r'^(defmodule|defprotocol)\s+([\w\.]+)',s)
