            # Ref weird: struct fields capture is off by one lines - second field's pattern line is "end". That suggests their parser creates field tags when closing? Let's reproduce struct field collection: collect identifiers inside struct and emit when we encounter them but their reported line numbers/patterns appear shifted? In sample: Point struct lines: struct(4) x(5) y(6) end(7) => tags: x with pattern line y (line6), y with pattern line end (line7). It looks like field tags' line is next line after field definition (maybe parser increments before making tag). For single sample could be bug due fields without types?
            # To match generic struct typed fields "x::Int" perhaps line is correct. For untyped simple identifiers, parser might treat next token as ... We'll implement normal fields, but for bare identifier lines inside struct we'll emulate shift: line idx+1 if next line exists.
            if stack: stack.pop()
            continue
        mf=re.match(r'^function\s+([A-Za-z_][\w!]*)',s)
        if mf: t=Tag(mf.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t); stack.append(('f',mf.group(1))); continue
        ms=re.match(r'^(mutable\s+)?struct\s+([A-Z][\w]*)',s)
        if ms: t=Tag(ms.group(2),display,idx+1,raw,'s',lang); t.roles="def"; tags.append(t); stack.append(('s',ms.group(2))); continue
        mm=re.match(r'^macro\s+([A-Za-z_][\w]*)',s)
        if mm: t=Tag(mm.group(1),display,idx+1,raw,'m',lang); t.roles="def"; tags.append(t); continue
        if stack and stack[-1][0]=='s':
            # field: name or name::Type
            ff=re.match(r'^([A-Za-z_][\w]*)(\s*::.*)?$',s)
            if ff:
                if ff.group(2):
                    t=Tag(ff.group(1),display,idx+1,raw,'g',lang); t.scope_kind_letter='s'; t.scope_name=stack[-1][1]; t.roles="def"; tags.append(t)
                else:
                    # shift line to next line to mimic ref for bare fields
                    nidx=min(idx+1,len(lines)-1)
                    t=Tag(ff.group(1),display,nidx+1,lines[nidx],'g',lang); t.scope_kind_letter='s'; t.scope_name=stack[-1][1]; t.roles="def"; tags.append(t)
            continue
        if stack and s:
            # inside function etc, no tags
            pass
    return tags

def parse_r_lang(state,path,display,lines,lang="R"):
    tags=[]
    for idx,raw in enumerate(lines):
        s=raw.strip()
        m=re.match(r'^([A-Za-z_][\w\.]*)\s*(?:<-|=)\s*function\s*\(',s)
        if m: t=Tag(m.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t); continue
        m=re.match(r'^([A-Za-z_][\w\.]*)\s*(?:<-|=)\s*setClass\s*\(',s)
        if m:
            # Both g and c tags for same, order g then c
            for kind in ('g','c'):
                t=Tag(m.group(1),display,idx+1,raw,kind,lang); t.roles="def"; tags.append(t)
            continue
    return tags

def parse_matlab(state,path,display,lines,lang="MatLab"):
    tags=[]; in_func=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mf=re.match(r'^function\s+(?:\[[^\]]*\]|[A-Za-z_]\w*)\s*=\s*([A-Za-z_]\w*)\s*\(',s)
        if mf: t=Tag(mf.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t); in_func=mf.group(1); continue
        mf2=re.match(r'^function\s+([A-Za-z_]\w*)\s*\(',s)
        if mf2: t=Tag(mf2.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t); in_func=mf2.group(1); continue
        if s=="end": in_func=None; continue
        # variable assignments at start? Ref y = x+1 inside function created v - seems MATLAB vars are tags (?) This could create many false assignments; only simple ^name =
        mv=re.match(r'^([A-Za-z_]\w*)\s*=(?!=)',s)
        if mv:
            t=Tag(mv.group(1),display,idx+1,raw,'v',lang); t.roles="def"; tags.append(t)
    return tags

def parse_tex(state,path,display,lines,lang="Tex"):
    tags=[]; chapter=None; section=None
    kindmap={'chapter':'c','section':'s','subsection':'u','subsubsection':'v','paragraph':'p'}
    for idx,raw in enumerate(lines):
        for m in re.finditer(r'\\(chapter|section|subsection|subsubsection|paragraph|label)\{([^}]+)\}',raw):
            kw=m.group(1); name=m.group(2)
            if kw=='label':
                t=Tag(name,display,idx+1,raw,'l',lang); t.roles="def"; tags.append(t)
            else:
                kind=kindmap.get(kw,'s'); t=Tag(name,display,idx+1,raw,kind,lang); t.roles="def"
                if kw=='subsection' and section:
                    t.scope_kind_letter='s'; t.scope_name=section
                elif kw=='subsubsection' and section:
                    t.scope_kind_letter='u'; t.scope_name=section
                tags.append(t)
                if kw=='chapter': chapter=name; section=None
                if kw=='section': section=name
    return tags

def parse_vim(state,path,display,lines,lang="Vim"):
    tags=[]
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mf=re.match(r'^function!?\s+([A-Za-z_][\w#:]*)\s*\(',s)
        if mf: t=Tag(mf.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t); continue
        mv=re.match(r'^let\s+([A-Za-z_][\w:#]*)\s*=',s)
        if mv: t=Tag(mv.group(1),display,idx+1,raw,'v',lang); t.roles="def"; tags.append(t); continue
        mc=re.match(r'^command!?\s+(?:-\S+\s+)*([A-Z][\w]*)',s)
        if mc: t=Tag(mc.group(1),display,idx+1,raw,'c',lang); t.roles="def"; tags.append(t)
    return tags

def parse_xml(state,path,display,lines,lang="XML"):
    # XML parser in ref for sample only gave id attr tag kind i - likely XPath based parsers for ant etc - generic XML may tag id attributes.
    tags=[]
    text="\n".join(lines)
    for m in re.finditer(r'\bid\s*=\s*"([^"]+)"',text):
        idx=text[:m.start()].count("\n")
        t=Tag(m.group(1),display,idx+1,lines[idx],'i',lang); t.roles="def"; tags.append(t)
    return tags

def parse_d_lang(state,path,display,lines,lang="D"):
    # D similar to C but module and class/struct etc. Use C parser for most, then fix kinds/scopes? C parser outputs class/struct etc with file logic similar to D sample: class Foo file:, struct Point file:, members file:, free function.
    tags=parse_c(state,path,display,lines,"C++")
    for t in tags: t.lang="D"
    # Add module tag at beginning if present
    result=[]
    for idx,raw in enumerate(lines):
        m=re.match(r'\s*module\s+([\w\.]+)\s*;',raw)
        if m:
            t=Tag(m.group(1),display,idx+1,raw,'M',"D"); t.roles="def"; result.append(t); break
    result.extend(tags)
    return result

