def parse_typescript(state,path,display,lines,lang="TypeScript"):
    # Based on JS plus interfaces/enums/type aliases/properties typed
    text="\n".join(lines); clean=strip_generic_comments(text); clines=clean.split("\n")
    tags=[]; stack=[]; brace_depth=0; pending=None
    def add(name,idx,kind,scope=None,signature=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope: t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.roles="def"; tags.append(t); return t
    def cur():
        for c in reversed(stack):
            if c.get('name'): return (c['kind'],c['full'])
        return None
    for idx,cline in enumerate(clines):
        line_pending=None; s=cline.strip()
        mi=re.search(r'\binterface\s+([A-Za-z_$][\w$]*)',cline)
        me=re.search(r'\benum\s+([A-Za-z_$][\w$]*)',cline)
        mc=re.search(r'\bclass\s+([A-Za-z_$][\w$]*)',cline)
        mt=re.search(r'\btype\s+([A-Za-z_$][\w$]*)\s*=',cline)
        if mi:
            name=mi.group(1); t=add(name,idx,'i',scope=cur()); line_pending=dict(name=name,full=name,kind='i',tag=t)
            mb=re.search(r'\{(.*)\}',cline)
            if mb:
                for part in mb.group(1).split(";"):
                    pm=re.match(r'\s*([A-Za-z_$][\w$]*)\s*:',part)
                    if pm: add(pm.group(1),idx,'p',scope=('i',name))
                line_pending=None
        elif me:
            name=me.group(1); t=add(name,idx,'g',scope=cur()); line_pending=dict(name=name,full=name,kind='g',tag=t)
            mb=re.search(r'\{(.*)\}',cline)
            if mb:
                for part in mb.group(1).split(","):
                    em=re.match(r'\s*([A-Za-z_$][\w$]*)',part)
                    if em: add(em.group(1),idx,'e',scope=('g',name))
                line_pending=None
        elif mc:
            name=mc.group(1); t=add(name,idx,'c',scope=cur()); line_pending=dict(name=name,full=name,kind='c',tag=t)
            # same-line members: properties with : and methods
            mb=re.search(r'\{(.*)\}\s*$',cline)
            if mb and '{' in cline and cline.count('{')>=1:
                content=mb.group(1)
                # This greedy content for nested method brace may be truncated at last }, fine for simple
                # properties split by ;
                # First extract methods to avoid treating as props
                method_spans=[]
                for mm in re.finditer(r'([A-Za-z_$][\w$]*)\s*\(([^)]*)\)\s*(?::[^{]+)?\{',content):
                    add(mm.group(1),idx,'m',scope=('c',name),signature="("+mm.group(2)+")"); method_spans.append(mm.group(1))
                for part in content.split(";"):
                    pm=re.match(r'\s*([A-Za-z_$][\w$]*)\s*:',part)
                    if pm and pm.group(1) not in method_spans:
                        # Ensure it's before any method brace section (?) property in test is before method
                        add(pm.group(1),idx,'p',scope=('c',name))
                    break  # only first segment is reliably property before method body; other props multi-line handled below
                # If class closes same line, line_pending will be handled by braces push/pop
        elif mt and brace_depth==0:
            add(mt.group(1),idx,'a',scope=cur())
        else:
            # function / const etc reuse JS patterns
            mf=re.search(r'\bfunction\s*\*?\s+([A-Za-z_$][\w$]*)\s*(?:<[^>]*>)?\s*\(([^)]*)\)',cline)
            if mf:
                add(mf.group(1),idx,'f',scope=cur(),signature="("+mf.group(2)+")")
            else:
                mv=re.search(r'\b(const|let|var)\s+([A-Za-z_$][\w$]*)\s*(?::[^=]+)?=\s*(.*)',cline)
                if mv and brace_depth==0:
                    kw=mv.group(1); name=mv.group(2); rhs=mv.group(3)
                    if re.match(r'.*=>|function\b',rhs):
                        add(name,idx,'f',scope=cur())
                    else:
                        add(name,idx,'C' if kw=='const' else 'v',scope=cur())
                elif stack and stack[-1].get('kind') in ('c','i') and brace_depth==stack[-1]['depth']:
                    mm=re.match(r'\s*(?:public|private|protected|static|async|\s)*([A-Za-z_$][\w$]*)\s*\(([^)]*)\)',cline)
                    if mm and '(' in cline and (s.endswith("{") or '{' in cline or s.endswith(";")):
                        add(mm.group(1),idx,'m',scope=cur(),signature="("+mm.group(2)+")")
                    else:
                        pm=re.match(r'\s*(?:public|private|protected|static|\s)*([A-Za-z_$][\w$]*)\s*[:;=\s]',cline)
                        if pm and (':' in cline or s.endswith(";")):
                            add(pm.group(1),idx,'p',scope=cur())
                elif stack and stack[-1].get('kind')=='g':
                    em=re.match(r'\s*([A-Za-z_$][\w$]*)',cline)
                    if em and s and not s.startswith("}"):
                        add(em.group(1),idx,'e',scope=cur())
        for ch in cline:
            if ch=='{':
                brace_depth+=1
                if line_pending:
                    ctx=dict(line_pending); ctx['depth']=brace_depth; stack.append(ctx); line_pending=None
                else:
                    stack.append(dict(name=None,full=None,kind=None,tag=None,depth=brace_depth))
            elif ch=='}':
                if stack: stack.pop()
                brace_depth=max(0,brace_depth-1)
    # Reorder same-line class properties/methods: In ref class single line, prop then method order as written. Our code added methods before prop in same content loop. Need sort tags on same line belonging to class scope by position in line. Since tags overall may be mostly line ordered, we can stable sort tags by (line_no, position of name in line) for TS only - class tag position name search finds class name first, prop next, method later. This preserves lines elsewhere.
    def pos_in_line(t):
        ln=lines[t.line_no-1]
        # find name as whole word after scope? Use first occurrence - class name may repeat etc but okay
        m=re.search(r'\b'+re.escape(t.name)+r'\b',ln)
        return m.start() if m else 0
    tags_sorted=sorted(tags,key=lambda t:(t.line_no,pos_in_line(t)))
    return tags_sorted

def parse_kotlin(state,path,display,lines,lang="Kotlin"):
    tags=[]; stack=[]; brace_depth=0; pkg=None; pending=None
    def add(name,idx,kind,scope=None,signature=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope: t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        t.signature=signature; t.roles="def"; tags.append(t); return t
    def cur():
        for c in reversed(stack):
            if c.get('name'): return (c['kind'],c['full'])
        if pkg: return ('p',pkg)
        return None
    for idx,raw in enumerate(lines):
        cline=strip_generic_comments(raw); s=cline.strip(); line_pending=None
        mp=re.match(r'package\s+([\w\.]+)',s)
        if mp:
            pkg=mp.group(1); add(pkg,idx,'p'); continue
        mc=re.search(r'\b(class|interface|object)\s+([A-Za-z_][\w]*)',cline)
        if mc:
            kw=mc.group(1); name=mc.group(2); kind={'class':'c','interface':'i','object':'o'}[kw]
            scope=cur(); t=add(name,idx,kind,scope=scope)
            full=(scope[1]+"."+name if scope else name)
            # If scope is package, full includes package as in com.example.Greeter
            line_pending=dict(name=name,full=full,kind=kind,tag=t)
            # same-line interface methods
            mb=re.search(r'\{(.*)\}',cline)
            if mb and 'fun ' in mb.group(1):
                for mm in re.finditer(r'fun\s+([A-Za-z_][\w]*)\s*\(([^)]*)\)',mb.group(1)):
                    add(mm.group(1),idx,'m',scope=(kind,full),signature="("+mm.group(2)+")")
        else:
            mf=re.search(r'\bfun\s+([A-Za-z_][\w]*)\s*\(([^)]*)\)',cline)
            if mf:
                # methods everywhere kind m in Kotlin (top-level also m per sample)
                add(mf.group(1),idx,'m',scope=cur(),signature="("+mf.group(2)+")")
            else:
                mv=re.match(r'\s*(val|var)\s+([A-Za-z_][\w]*)',cline)
                if mv:
                    kind='C' if mv.group(1)=='val' else 'v'
                    add(mv.group(2),idx,kind,scope=cur())
        for ch in cline:
            if ch=='{':
                brace_depth+=1
                if line_pending:
                    ctx=dict(line_pending); ctx['depth']=brace_depth; stack.append(ctx); line_pending=None
                else:
                    stack.append(dict(name=None,full=None,kind=None,tag=None,depth=brace_depth))
            elif ch=='}':
                if stack: stack.pop()
                brace_depth=max(0,brace_depth-1)
    return tags

def parse_iniconf(state,path,display,lines,lang="Iniconf"):
    tags=[]; section=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        m=re.match(r'\[([^\]]+)\]',s)
        if m:
            section=m.group(1); t=Tag(section,display,idx+1,raw,'s',lang); t.roles="def"; tags.append(t); continue
        mk=re.match(r'^([A-Za-z0-9_.-]+)\s*=',s)
        if mk:
            t=Tag(mk.group(1),display,idx+1,raw,'k',lang); t.roles="def"
            if section: t.scope_kind_letter='s'; t.scope_name=section
            tags.append(t)
    return tags

def parse_erlang(state,path,display,lines,lang="Erlang"):
    tags=[]; mod=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mm=re.match(r'-module\((\w+)\)\.',s)
        if mm: mod=mm.group(1); t=Tag(mod,display,idx+1,raw,'m',lang); t.roles="def"; tags.append(t); continue
        mr=re.match(r'-record\((\w+),',s)
        if mr: t=Tag(mr.group(1),display,idx+1,raw,'r',lang); t.roles="def"; tags.append(t); continue
        md=re.match(r'-define\((\w+),',s)
        if md: t=Tag(md.group(1),display,idx+1,raw,'d',lang); t.roles="def"; tags.append(t); continue
        mf=re.match(r'^([a-z][\w]*)\s*\(([^)]*)\)\s*->',s)
        if mf:
            t=Tag(mf.group(1),display,idx+1,raw,'f',lang); t.roles="def"
            if mod: t.scope_kind_letter='m'; t.scope_name=mod
            tags.append(t)
    return tags

def parse_elixir(state,path,display,lines,lang="Elixir"):
    tags=[]; stack=[]
    for idx,raw in enumerate(lines):
        s=raw.strip()
        if s=="end":
            if stack: stack.pop()
            continue
        mm=re.match(r'^(defmodule|defprotocol)\s+([\w\.]+)',s)
        if mm:
            kind='m' if mm.group(1)=='defmodule' else 'p'
            t=Tag(mm.group(2),display,idx+1,raw,kind,lang); t.roles="def"; tags.append(t); stack.append(mm.group(2)); continue
