            t=Tag(mf.group(2),display,idx+1,raw,'f',lang); t.roles="def"
            if stack: t.scope_kind_letter='m'; t.scope_name=stack[-1]
            tags.append(t)
    return tags

def parse_fortran(state,path,display,lines,lang="Fortran"):
    tags=[]; stack=[]  # (name,kind)
    def add(name,idx,kind,scope=None,pattern_override=None):
        t=Tag(name,display,idx+1,lines[idx],kind,lang)
        if scope: t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
        if pattern_override: t.pattern_override=pattern_override
        t.roles="def"; tags.append(t); return t
    for idx,raw in enumerate(lines):
        s=raw.strip()
        low=s.lower()
        if low.startswith("end "):
            if stack: stack.pop()
            continue
        mp=re.match(r'^(program|module|subroutine|function)\s+([A-Za-z_]\w*)',low)
        if mp:
            kindmap={'program':'p','module':'m','subroutine':'s','function':'f'}
            name=s.split()[1].split('(')[0]
            # name case preserve from source second token
            pat=None
            if mp.group(1) in ('subroutine','function'):
                pat=raw[:raw.find('(')+1] if '(' in raw else None
            t=add(name,idx,kindmap[mp.group(1)],pattern_override=pat)
            stack.append((name,kindmap[mp.group(1)]))
            continue
        # variable declarations inside program: "integer :: count"
        mv=re.match(r'^(integer|real|character|logical|double precision|complex)(?:\s*\([^)]*\))?\s*::\s*(.+)$',low)
        if mv and stack:
            rest=s.split("::",1)[1]
            for part in rest.split(","):
                nm=part.strip().split('=')[0].split('(')[0].strip()
                if re.match(r'^[A-Za-z_]\w*$',nm):
                    add(nm,idx,'v',scope=(stack[-1][1],stack[-1][0]))
    return tags

def parse_pascal(state,path,display,lines,lang="Pascal"):
    tags=[]
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mp=re.match(r'^procedure\s+([A-Za-z_]\w*)',s,re.I)
        if mp: t=Tag(mp.group(1),display,idx+1,raw,'p',lang); t.roles="def"; tags.append(t); continue
        mf=re.match(r'^function\s+([A-Za-z_]\w*)\s*(?:\(([^)]*)\))?\s*:\s*([A-Za-z_]\w*)',s,re.I)
        if mf:
            t=Tag(mf.group(1),display,idx+1,raw,'f',lang); t.roles="def"; t.typeref="typename:"+mf.group(3); tags.append(t); continue
        mf2=re.match(r'^function\s+([A-Za-z_]\w*)',s,re.I)
        if mf2: t=Tag(mf2.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t); continue
    return tags

def parse_ada(state,path,display,lines,lang="Ada"):
    tags=[]; pkg=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mp=re.match(r'^package\s+([A-Za-z_]\w*)\s+is',s,re.I)
        if mp: pkg=mp.group(1); t=Tag(pkg,display,idx+1,raw,'P',lang); t.roles="def"; tags.append(t); continue
        if re.match(r'^end\s+',s,re.I): pkg=None; continue
        scope=('P',pkg) if pkg else None
        mpr=re.match(r'^(procedure|function)\s+([A-Za-z_]\w*)',s,re.I)
        if mpr:
            t=Tag(mpr.group(2),display,idx+1,raw,'R',lang); t.roles="def"
            if scope: t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
            tags.append(t); continue
        mt=re.match(r'^type\s+([A-Za-z_]\w*)',s,re.I)
        if mt:
            t=Tag(mt.group(1),display,idx+1,raw,'t',lang); t.roles="def"
            if scope: t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
            tags.append(t); continue
        mv=re.match(r'^([A-Za-z_]\w*)\s*:\s*[A-Za-z_]',s)
        if mv and s.endswith(";"):
            t=Tag(mv.group(1),display,idx+1,raw,'v',lang); t.roles="def"
            if scope: t.scope_kind_letter=scope[0]; t.scope_name=scope[1]
            tags.append(t)
    # scope kind name for P in Ada is packspec, rendering scope:packspec if Z, default scope field format uses kind name (packspec) good.
    return tags

def parse_haskell(state,path,display,lines,lang="Haskell"):
    tags=[]
    for idx,raw in enumerate(lines):
        s=raw.strip()
        if raw and not raw[0].isspace():
            mm=re.match(r'^module\s+([A-Z][\w\.]*)',s)
            if mm: t=Tag(mm.group(1),display,idx+1,raw,'m',lang); t.roles="def"; tags.append(t); continue
            md=re.match(r'^data\s+([A-Z][\w]*)\b.*=\s*([A-Z][\w]*)',s)
            if md:
                t=Tag(md.group(1),display,idx+1,raw,'t',lang); t.roles="def"; tags.append(t)
