def parse_bibtex(state,path,display,lines,lang="BibTeX"):
    tags=[]
    for idx,raw in enumerate(lines):
        m=re.match(r'\s*@(\w+)\s*\{\s*([^,\s]+)',raw)
        if m:
            typ=m.group(1).lower()
            kind={'article':'a','book':'b','booklet':'B','conference':'c','inbook':'i','incollection':'I','inproceedings':'c','manual':'m','mastersthesis':'t','misc':'t','phdthesis':'p','proceedings':'P','techreport':'r','unpublished':'u'}.get(typ,'t')
            # fallback check meta kinds names
            kbyname=meta().kind_by_name.get(lang,{})
            if typ in kbyname: kind=kbyname[typ]['letter']
            t=Tag(m.group(2),display,idx+1,raw,kind,lang); t.roles="def"; tags.append(t)
    return tags

def parse_awk(state,path,display,lines,lang="Awk"):
    tags=[]
    for idx,raw in enumerate(lines):
        m=re.match(r'\s*function\s+([A-Za-z_]\w*)\s*\(',raw)
        if m: t=Tag(m.group(1),display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t)
    return tags

def parse_tcl(state,path,display,lines,lang="Tcl"):
    tags=[]; ns_stack=[]
    brace_depth=0
    for idx,raw in enumerate(lines):
        s=raw.strip()
        mns=re.match(r'^namespace\s+eval\s+([^\s{]+)',s)
        if mns:
            name=mns.group(1); t=Tag(name,display,idx+1,raw,'n',lang); t.roles="def"; tags.append(t); ns_stack.append(name)
            # brace counting below will need pop on } - simplistic: if line has { keep until line is }
            continue
        if s=="}":
            if ns_stack: ns_stack.pop()
            continue
        mp=re.match(r'^(?:proc)\s+([^\s{]+)',s)
        if mp:
            t=Tag(mp.group(1),display,idx+1,raw,'p',lang); t.roles="def"
            if ns_stack: t.scope_kind_letter='n'; t.scope_name="::"+ns_stack[-1]
            tags.append(t)
    return tags

def parse_lisp_family(state,path,display,lines,lang):
    tags=[]
    if lang=="Lisp":
        patterns=[(r'^\(defun\s+([^\s\(\)]+)','f'),(r'^\(defmacro\s+([^\s\(\)]+)','m'),(r'^\(defvar\s+([^\s\(\)]+)','v'),(r'^\(defparameter\s+([^\s\(\)]+)','v'),(r'^\(defconstant\s+([^\s\(\)]+)','v'),(r'^\(defclass\s+([^\s\(\)]+)','C'),(r'^\(defstruct\s+([^\s\(\)]+)','s'),(r'^\(defgeneric\s+([^\s\(\)]+)','f'),(r'^\(defmethod\s+([^\s\(\)]+)','f')]
        for idx,raw in enumerate(lines):
            for pat,kind in patterns:
                m=re.match(pat,raw)
                if m: t=Tag(m.group(1),display,idx+1,raw,kind,lang); t.roles="def"; tags.append(t); break
        return tags
    if lang=="Scheme":
        for idx,raw in enumerate(lines):
            m=re.match(r'^\((define)\s+(?:\(\s*([^\s\(\)]+)|([^\s\(\)]+))',raw)
            if m:
                name=m.group(2) or m.group(3); t=Tag(name,display,idx+1,raw,'f',lang); t.roles="def"; tags.append(t)
        return tags
    if lang=="Clojure":
        ns=None
        for idx,raw in enumerate(lines):
            mns=re.match(r'^\((?:ns|in-ns)\s+([^\s\(\)]+)',raw)
            if mns: ns=mns.group(1); t=Tag(ns,display,idx+1,raw,'n',lang); t.roles="def"; tags.append(t); continue
            m=re.match(r'^\((defn|defn-|def|defonce|defrecord|deftype|defprotocol|defmacro)\s+([^\s\(\)\[]+)',raw)
            if m:
                kind={'defn':'f','defn-':'f','def':'v','defonce':'v','defrecord':'r','deftype':'t','defprotocol':'p','defmacro':'m'}.get(m.group(1),'f')
                # In sample def & defrecord apparently NOT tagged? ref only defn. So only emit defn/defn-/defmacro? Let's only emit function defs & namespaces as observed.
                if m.group(1) not in ('defn','defn-','defmacro'):
                    continue
                t=Tag(m.group(2),display,idx+1,raw,kind,lang); t.roles="def"
                if ns: t.scope_kind_letter='n'; t.scope_name=ns
                tags.append(t)
        return tags
    return tags

def parse_ocaml(state,path,display,lines,lang="OCaml"):
    tags=[]
    # Module name from filename Titlecase first letter at first tag line1 pattern (?) Sample file test.ml gave M tag "Test" on first let line. General OCaml creates implicit module from filename.
    base=os.path.splitext(os.path.basename(display))[0]
    modname=base[:1].upper()+base[1:] if base else None
    mod_added=False; current_module=None
    for idx,raw in enumerate(lines):
        s=raw.strip()
        if modname and not mod_added and s:
            t=Tag(modname,display,idx+1,raw,'M',lang); t.roles="def"; tags.append(t); mod_added=True
        mm=re.match(r'^module\s+([A-Z][\w]*)',s)
        if mm:
            current_module=mm.group(1); t=Tag(current_module,display,idx+1,raw,'M',lang); t.roles="def"; tags.append(t); continue
        if s=="end":
            current_module=None; continue
        mt=re.match(r'^type\s+(?:\S+\s+)?([a-z_][\w]*)',s)
        if mt:
            # Avoid type with parameter confusion; name is last identifier before = if params precede? Simple sample.
            name=s.split("=")[0].strip().split()[-1]
            t=Tag(name,display,idx+1,raw,'t',lang); t.roles="def"; tags.append(t)
            # record fields inside {}
            mb=re.search(r'\{(.*)\}',raw)
            if mb:
                for part in mb.group(1).split(";"):
                    fm=re.match(r'\s*(?:mutable\s+)?([a-z_][\w]*)',part)
                    if fm: tt=Tag(fm.group(1),display,idx+1,raw,'r',lang); tt.scope_kind_letter='t'; tt.scope_name=name; tt.roles="def"; tags.append(tt)
            continue
        ml=re.match(r'^let\s+(?:rec\s+)?([A-Za-z_][\w]*)',s) if not raw.startswith(" ") and not raw.startswith("\t") else re.match(r'^let\s+(?:rec\s+)?([A-Za-z_][\w]*)',s)
        if ml:
            rest=s[ml.end():].strip()
            # function if there's argument before = or result looks func: sample my_func x = ; my_var = is v; inner in module = v.
            # Determine: text between name and '=' non-empty => function
            before_eq=rest.split("=",1)[0].strip() if "=" in rest else ""
            kind='f' if before_eq else 'v'
            t=Tag(ml.group(1),display,idx+1,raw,kind,lang); t.roles="def"
            if current_module: t.scope_kind_letter='M'; t.scope_name=current_module
            tags.append(t)
    return tags

def parse_org(state,path,display,lines,lang="Org"):
    tags=[]; kinds=['p','c','s','S','t','T']
    for idx,raw in enumerate(lines):
        m=re.match(r'^(\*{1,6})\s+(.+)$',raw)
        if m:
            lvl=len(m.group(1))-1; kind=kinds[lvl] if lvl < len(kinds) else 's'
            t=Tag(m.group(2).strip(),display,idx+1,raw,kind,lang); t.roles="def"; tags.append(t)
    return tags

def parse_rst(state,path,display,lines,lang="ReStructuredText"):
    tags=[]
    # overline/underline punctuation determines level by order of first appearance of punctuation char
    seen={}; kinds=['H','h','c','s','S','t']
    # scope mapping: H title, h (?) name in meta for h is "subtitle" maybe scope of Sub (level3 c?) was subtitle:Section meaning parent kind name for h is subtitle. And Section h scope title:Title (parent H name title).
    stack=[]
    for idx,raw in enumerate(lines):
        if idx+1 < len(lines) and raw.strip():
            nxt=lines[idx+1].strip()
            if nxt and len(set(nxt))==1 and nxt[0] in "=-^~\"'#*+_" and len(nxt)>=len(raw.strip()):
                punct=nxt[0]
                if punct not in seen: seen[punct]=len(seen)
                lvl=seen[punct]; kind=kinds[lvl] if lvl < len(kinds) else 's'
                name=raw.strip()
                while stack and stack[-1][0]>=lvl: stack.pop()
                t=Tag(name,display,idx+1,raw,kind,lang); t.roles="def"
                if stack: t.scope_kind_letter=stack[-1][2]; t.scope_name=stack[-1][1]
                tags.append(t); stack.append((lvl,name,kind))
    return tags

def parse_diff(state,path,display,lines,lang="Diff"):
    tags=[]; current=None
    for idx,raw in enumerate(lines):
        m=re.match(r'^---\s+(\S+)',raw)
        if m:
            current=m.group(1); t=Tag(current,display,idx+1,raw,'m',lang); t.roles="def"; tags.append(t); continue
        mh=re.match(r'^@@\s+( -\d+,\d+ \+\d+,\d+|\S+)\s*@@',raw)
        if mh:
            # name from sample "-1,3 +1,3" without spaces edges
            m2=re.match(r'^@@\s+(-\d+,\d+ \+\d+,\d+)\s+@@',raw)
            name=m2.group(1) if m2 else mh.group(1).strip()
            t=Tag(name,display,idx+1,raw,'h',lang); t.roles="def"
            if current: t.scope_kind_letter='m'; t.scope_name=current
            tags.append(t)
    return tags

